export const GL=[
/* ---------- FARMACI ---------- */
["glargine","Insulina glargine","Farmaco",["insulina glargine","glargine"],{pa:"Insulina glargine (analogo dell'insulina umana ad azione lenta).",cl:"Insulina basale, ad azione prolungata.",mec:"Iniettata sottocute forma microprecipitati che si sciolgono lentamente: rilascia insulina in modo quasi costante per circa 24 ore, senza un picco marcato. Copre il bisogno di insulina tra i pasti e di notte.",ind:"Diabete tipo 1 e tipo 2 in schema basale o basal-bolus.",vie:"Sottocute, una volta al giorno alla stessa ora. Dose personalizzata in unità.",av:"Ipoglicemia (soprattutto notturna), lipodistrofia nei siti di iniezione ripetuti, aumento di peso.",int:"Betabloccanti (mascherano i sintomi dell'ipoglicemia), corticosteroidi (alzano la glicemia), alcol (aumenta il rischio di ipoglicemia), ACE-inibitori (possono aumentare la sensibilità all'insulina).",inf:"Non va mescolata con altre insuline nella stessa siringa. Ruotare i siti di iniezione. Nel paziente che non mangia di solito non si sospende, ma la dose si concorda con il medico."},["insulina","lispro","ipoglicemia","diabete","basalbolus"]],
["lispro","Insulina lispro","Farmaco",["insulina lispro","lispro","insulina rapida"],{pa:"Insulina lispro (analogo rapido dell'insulina umana).",cl:"Insulina prandiale ad azione rapida.",mec:"Una piccola modifica della molecola le impedisce di aggregarsi: viene assorbita in fretta. Inizia ad agire in 10-15 minuti, picco a 1-2 ore, durata 3-5 ore. Copre l'aumento di glicemia dopo il pasto.",ind:"Diabete in schema basal-bolus, correzione delle iperglicemie, infusione EV in alcuni protocolli.",vie:"Sottocute subito prima del pasto (o subito dopo, se il paziente mangia in modo incerto). EV solo in infusione, secondo protocollo.",av:"Ipoglicemia, soprattutto se il pasto non viene consumato. Ipokaliemia ad alte dosi EV.",int:"Come le altre insuline: betabloccanti, corticosteroidi, alcol, sulfaniluree.",inf:"In un paziente con nausea o che mangia poco, valutare con il medico la somministrazione dopo il pasto in base a quanto ha mangiato."},["insulina","glargine","ipoglicemia"]],
["insulina","Insulina","Ormone · Farmaco",["insulin[ae]"],{d:"Ormone prodotto dalle cellule beta delle isole di Langerhans del pancreas. Permette al glucosio di entrare nelle cellule di muscolo e tessuto adiposo, stimola la sintesi di glicogeno nel fegato e blocca la produzione di glucosio e di corpi chetonici.",ap:"Sposta anche il potassio dentro le cellule: per questo si usa (con glucosio) nell'iperkaliemia, e per questo nella chetoacidosi si controlla il potassio prima di avviarla. Come farmaco esiste in forme rapide, intermedie e lente."},["cellulebeta","glargine","lispro","ipoglicemia","chetoacidosi","potassio","glut"]],
["glucagone","Glucagone","Ormone · Farmaco",["glucagone"],{pa:"Glucagone (ormone peptidico prodotto per via ricombinante).",cl:"Ormone iperglicemizzante.",mec:"Stimola il fegato a liberare glucosio dalle riserve di glicogeno (glicogenolisi) e a produrne di nuovo (gluconeogenesi). Funziona solo se il fegato ha riserve di glicogeno.",ind:"Ipoglicemia grave quando il paziente non può assumere zuccheri per bocca (incosciente, convulsioni, vomito).",vie:"1 mg IM o sottocute nell'adulto; esiste anche una forma nasale. Effetto in circa 10-15 minuti.",av:"Nausea e vomito frequenti, tachicardia.",int:"Potenzia l'effetto del warfarin. Meno efficace in chi ha riserve di glicogeno esaurite (digiuno prolungato, alcolismo).",inf:"Dopo il risveglio dare zuccheri per bocca e poi un pasto, perché l'effetto dura poco. Mettere il paziente su un fianco per il rischio di vomito."},["cellulealfa","ipoglicemia","glicogenolisi","gluconeogenesi"]],
["glucosio33","Glucosio ipertonico (33%)","Farmaco",["glucosio 33%","glucosio ev"],{pa:"Glucosio (destrosio) in soluzione.",cl:"Soluzione glucosata; al 5% isotonica, al 10% e 33% ipertonica.",mec:"Fornisce glucosio direttamente nel sangue.",ind:"Ipoglicemia grave in paziente che non può usare la via orale; aggiunta alle infusioni di insulina (iperkaliemia, chetoacidosi) per evitare ipoglicemie.",vie:"EV. Le concentrazioni alte vanno in vene di buon calibro, lentamente.",av:"Flebite e danno tissutale se stravasa (soluzioni ipertoniche), iperglicemia, sovraccarico di liquidi.",int:"Con insulina: è usato proprio per bilanciarne l'effetto ipoglicemizzante.",inf:"Controllare l'accesso venoso prima e durante. Ricontrollare la glicemia dopo 10-15 minuti."},["ipoglicemia","flebite","glucosata"]],
["ramipril","Ramipril","Farmaco",["ramipril"],{pa:"Ramipril.",cl:"ACE-inibitore (inibitore dell'enzima di conversione dell'angiotensina).",mec:"Riduce la formazione di angiotensina II: i vasi si dilatano, cala la secrezione di aldosterone, il cuore lavora contro una resistenza minore.",ind:"Ipertensione, scompenso cardiaco, dopo infarto, protezione renale nel diabete.",vie:"Per os, 1,25-10 mg al giorno.",av:"Tosse secca, ipotensione (soprattutto alla prima dose o con diuretici), iperkaliemia, peggioramento della funzione renale, angioedema (raro ma grave).",int:"Con integratori o sostituti del sale al potassio, spironolattone e altri risparmiatori di potassio: rischio di iperkaliemia. Con FANS: ridotto effetto e danno renale. Con diuretici: ipotensione.",inf:"Controllare PA, creatinina e potassio. Chiedere sempre dei sostituti del sale."},["acei","iperkaliemia","aldosterone","sostitutosale","angioedema"]],
["acei","ACE-inibitori","Classe di farmaci",["ace-inibitor[ie]"],{d:"Farmaci che bloccano l'enzima che trasforma l'angiotensina I in angiotensina II. Ne fanno parte ramipril, enalapril, lisinopril.",ap:"Abbassano la pressione e riducono il lavoro del cuore. Effetti tipici: tosse secca (per accumulo di bradichinina), iperkaliemia, angioedema."},["ramipril","iperkaliemia"]],
["furosemide","Furosemide","Farmaco",["furosemide"],{pa:"Furosemide.",cl:"Diuretico dell'ansa.",mec:"Blocca il cotrasportatore Na⁺-K⁺-2Cl⁻ nel tratto ascendente spesso dell'ansa di Henle: più sodio resta nel tubulo e porta con sé acqua. Per via EV ha anche un rapido effetto venodilatatore.",ind:"Edema polmonare, scompenso cardiaco con congestione, edemi da cirrosi o malattie renali, a volte iperkaliemia.",vie:"Per os o EV (bolo lento o infusione). Effetto EV in 5-30 minuti.",av:"Ipokaliemia, iponatriemia, ipomagnesiemia, disidratazione, ipotensione, peggioramento della funzione renale, ototossicità (dosi alte EV rapide), gotta.",int:"Con digossina: l'ipokaliemia aumenta la tossicità della digossina. Con aminoglicosidi: maggiore ototossicità. Con litio: ne aumenta i livelli. Con ACE-inibitori: ipotensione.",inf:"Bilancio idrico e peso giornaliero, PA, potassio e creatinina. Somministrare preferibilmente al mattino e nel primo pomeriggio. Attenzione alle cadute per urgenza minzionale e ipotensione."},["ansahenle","ipokaliemia","edemapolmonare","scompenso","bilancioidrico"]],
["diureticiansa","Diuretici dell'ansa","Classe di farmaci",["diuretic[oi] dell'ansa"],{d:"I diuretici più potenti: furosemide, torasemide, bumetanide. Agiscono nel tratto ascendente spesso dell'ansa di Henle.",ap:"Fanno perdere sodio, acqua, potassio, magnesio e calcio."},["furosemide","ansahenle"]],
["tiazidici","Diuretici tiazidici","Classe di farmaci",["tiazidic[io]"],{d:"Diuretici come idroclorotiazide e clortalidone. Bloccano il cotrasportatore Na⁺-Cl⁻ nel tubulo contorto distale.",ap:"Meno potenti dei diuretici dell'ansa, usati soprattutto nell'ipertensione. Possono dare ipokaliemia, iponatriemia, iperglicemia e iperuricemia; al contrario dei diuretici dell'ansa riducono il calcio nelle urine."},["tubulodistale","ipokaliemia"]],
["spironolattone","Spironolattone","Farmaco",["spironolattone"],{pa:"Spironolattone.",cl:"Diuretico risparmiatore di potassio, antagonista dell'aldosterone.",mec:"Blocca i recettori dell'aldosterone nel dotto collettore: meno sodio riassorbito, meno potassio eliminato.",ind:"Scompenso cardiaco con frazione d'eiezione ridotta, ascite da cirrosi, iperaldosteronismo.",vie:"Per os, 25-100 mg al giorno.",av:"Iperkaliemia, ginecomastia, peggioramento della funzione renale.",int:"Con ACE-inibitori, sartani, integratori di potassio: rischio elevato di iperkaliemia.",inf:"Potassio e creatinina regolari, soprattutto nei primi mesi e negli anziani."},["aldosterone","dottocollettore","iperkaliemia"]],
["acetazolamide","Acetazolamide","Farmaco",["acetazolamide"],{pa:"Acetazolamide.",cl:"Inibitore dell'anidrasi carbonica.",mec:"Riduce il riassorbimento di bicarbonato nel tubulo contorto prossimale: urine alcaline e acidosi metabolica lieve.",ind:"Glaucoma, mal di montagna, alcune forme di epilessia, alcalosi metabolica.",vie:"Per os o EV.",av:"Parestesie, ipokaliemia, acidosi metabolica, calcoli renali.",int:"Con aspirina ad alte dosi: tossicità.",inf:"Controllare elettroliti e idratazione."},["tubuloprossimale"]],
["bisoprololo","Bisoprololo","Farmaco",["bisoprololo"],{pa:"Bisoprololo.",cl:"Betabloccante cardioselettivo (β1).",mec:"Blocca i recettori β1 del cuore: riduce frequenza, forza di contrazione e consumo di ossigeno.",ind:"Scompenso cardiaco con frazione d'eiezione ridotta, cardiopatia ischemica, controllo della frequenza nella fibrillazione atriale, ipertensione.",vie:"Per os, 1,25-10 mg al giorno.",av:"Bradicardia, ipotensione, astenia, peggioramento dello scompenso se iniziato a dosi alte, broncospasmo (meno dei non selettivi).",int:"Con verapamil o diltiazem: bradicardia e blocchi. Con insulina: maschera tremore e tachicardia dell'ipoglicemia. Riduce l'efficacia del salbutamolo e dell'adrenalina.",inf:"Controllare FC e PA prima della somministrazione: di solito si segnala una FC sotto 50-55. Non sospendere bruscamente."},["betabloccanti","recettorib1","ipoglicemia"]],
["betabloccanti","Betabloccanti","Classe di farmaci",["betabloccant[ei]"],{d:"Farmaci che bloccano i recettori β dell'adrenalina: bisoprololo, metoprololo, carvedilolo, propranololo.",ap:"Rallentano il cuore e ne riducono il lavoro. Possono mascherare i segni adrenergici dell'ipoglicemia e ridurre la risposta all'adrenalina nell'anafilassi."},["bisoprololo","recettorib1","recettorib2"]],
["apixaban","Apixaban","Farmaco",["apixaban"],{pa:"Apixaban.",cl:"Anticoagulante orale diretto (DOAC), inibitore del fattore Xa.",mec:"Blocca il fattore X attivato della coagulazione: si forma meno trombina e quindi meno fibrina.",ind:"Prevenzione dell'ictus nella fibrillazione atriale non valvolare, trattamento e prevenzione di trombosi venosa ed embolia polmonare.",vie:"Per os, di solito 5 mg due volte al giorno (2,5 mg in alcuni pazienti).",av:"Sanguinamenti: gengive, naso, urine, apparato digerente, cervello.",int:"Con antiaggreganti e FANS: più sanguinamenti. Con alcuni antifungini azolici e antiretrovirali: livelli più alti. Con rifampicina, carbamazepina, iperico: livelli più bassi.",inf:"Non saltare dosi. La sospensione deve essere decisa e comunicata: espone a ictus nella fibrillazione atriale. Osservare segni di sanguinamento."},["anticoagulante","fibrillazioneatriale","ictus","embolia"]],
["anticoagulante","Anticoagulante","Classe di farmaci",["anticoagulant[ei]"],{d:"Farmaco che riduce la capacità del sangue di coagulare. Comprende eparine (enoxaparina), anticoagulanti orali diretti (apixaban, rivaroxaban, dabigatran, edoxaban) e antagonisti della vitamina K (warfarin).",ap:"Previene la formazione e la crescita dei trombi ma non scioglie quelli già formati: quello è il compito dei trombolitici."},["apixaban","enoxaparina","alteplase","trombo"]],
["enoxaparina","Enoxaparina","Farmaco",["enoxaparina"],{pa:"Enoxaparina sodica.",cl:"Eparina a basso peso molecolare.",mec:"Potenzia l'antitrombina, che inattiva soprattutto il fattore Xa.",ind:"Profilassi della trombosi venosa dopo chirurgia o in pazienti allettati (es. 4000 UI una volta al giorno), trattamento di trombosi ed embolia (dose in base al peso).",vie:"Sottocute, nella parete addominale.",av:"Sanguinamento, ematomi nel sito, piastrinopenia indotta da eparina (HIT).",int:"Con antiaggreganti, FANS, altri anticoagulanti: più sanguinamenti.",inf:"Non espellere la bolla d'aria della siringa preriempita, non massaggiare dopo l'iniezione, alternare i lati dell'addome. Controllare le piastrine. Un rifiuto della dose va segnalato."},["anticoagulante","tvp","virchow"]],
["paracetamolo","Paracetamolo","Farmaco",["paracetamolo"],{pa:"Paracetamolo (acetaminofene).",cl:"Analgesico e antipiretico.",mec:"Agisce soprattutto a livello centrale riducendo la sintesi di prostaglandine. Ha scarso effetto antinfiammatorio.",ind:"Dolore lieve-moderato, febbre; parte dell'analgesia multimodale dopo chirurgia.",vie:"Per os o EV, 1 g ogni 6-8 ore nell'adulto; massimo di solito 3-4 g al giorno (meno nel paziente fragile, sotto i 50 kg o con epatopatia).",av:"Ben tollerato alle dosi corrette. Il sovradosaggio causa grave danno al fegato.",int:"Con warfarin: può aumentarne l'effetto con l'uso regolare. Alcol cronico: più rischio epatico.",inf:"Controllare tutti i prodotti assunti (molti farmaci da banco lo contengono). Abbassa la febbre ma non ne tratta la causa."},["febbre"]],
["tiotropio","Tiotropio / olodaterolo","Farmaco",["tiotropio\\/olodaterolo","tiotropio","olodaterolo"],{pa:"Tiotropio (anticolinergico a lunga durata, LAMA) + olodaterolo (β2-agonista a lunga durata, LABA).",cl:"Broncodilatatori inalatori per la terapia di mantenimento.",mec:"Il tiotropio blocca i recettori muscarinici bronchiali; l'olodaterolo stimola i β2. Insieme rilasciano la muscolatura bronchiale per 24 ore.",ind:"BPCO di mantenimento. Non sono farmaci per la crisi acuta.",vie:"Inalatoria, una volta al giorno.",av:"Secchezza delle fauci, ritenzione urinaria (anticolinergico), tachicardia, tremore (β2).",int:"Con betabloccanti non selettivi: effetto ridotto. Con altri anticolinergici: effetti additivi.",inf:"Controllare la tecnica inalatoria, una delle cause più frequenti di scarsa efficacia."},["bpco","salbutamolo","recettorib2"]],
["salbutamolo","Salbutamolo","Farmaco",["salbutamolo"],{pa:"Salbutamolo.",cl:"β2-agonista a breve durata d'azione (SABA).",mec:"Stimola i recettori β2 della muscolatura bronchiale e la rilascia in pochi minuti. Sposta anche il potassio dentro le cellule.",ind:"Broncospasmo in asma e BPCO, broncospasmo residuo nell'anafilassi, iperkaliemia (per nebulizzazione, ad alte dosi).",vie:"Spray predosato (con distanziatore), nebulizzazione, raramente EV.",av:"Tachicardia, palpitazioni, tremore, ipokaliemia, iperglicemia.",int:"Betabloccanti ne riducono l'effetto. Con diuretici e corticosteroidi: più ipokaliemia.",inf:"Insegnare l'uso del distanziatore. Monitorare FC; nei trattamenti ripetuti controllare il potassio."},["recettorib2","broncospasmo","asma","bpco"]],
["morfina","Morfina","Farmaco",["morfina"],{pa:"Morfina solfato o cloridrato.",cl:"Oppioide agonista dei recettori μ.",mec:"Attiva i recettori μ nel sistema nervoso centrale e nel midollo spinale: riduce la trasmissione e la percezione del dolore.",ind:"Dolore moderato-severo (post-operatorio, oncologico), dispnea nelle cure palliative.",vie:"EV, sottocute, per os, in PCA. Dosi titolate sul singolo paziente.",av:"Depressione respiratoria, sedazione, nausea e vomito, stipsi, ritenzione urinaria, prurito, ipotensione, miosi.",int:"Con benzodiazepine, gabapentinoidi, alcol, altri sedativi: depressione respiratoria aumentata. In insufficienza renale si accumulano metaboliti attivi.",inf:"Valutare dolore, sedazione e FR prima e dopo ogni dose. Prevenire la stipsi. Tenere disponibile il naloxone."},["oppioidi","recettorimu","naloxone","pca","depressionerespiratoria","miosi"]],
["oppioidi","Oppioidi","Classe di farmaci",["oppioid[ie]"],{d:"Farmaci che agiscono sui recettori degli oppioidi: morfina, ossicodone, fentanyl, idromorfone, tramadolo, buprenorfina.",ap:"Sono gli analgesici più potenti. Il rischio principale è la depressione respiratoria, preceduta di solito dalla sedazione."},["morfina","recettorimu","naloxone","depressionerespiratoria"]],
["naloxone","Naloxone","Farmaco",["naloxone"],{pa:"Naloxone cloridrato.",cl:"Antagonista puro dei recettori degli oppioidi.",mec:"Occupa i recettori μ (e in misura minore κ e δ) senza attivarli, spostando l'oppioide. Agisce in 1-2 minuti per via EV; dura circa 30-90 minuti.",ind:"Depressione respiratoria e sedazione da oppioidi.",vie:"EV in piccoli boli titolati in ospedale (es. 40-100 microgrammi), IM, sottocute o intranasale fuori dall'ospedale. Infusione continua se serve.",av:"Inversione brusca: dolore intenso, agitazione, ipertensione, tachicardia, aritmie, raramente edema polmonare. Sindrome d'astinenza nei pazienti dipendenti.",int:"Antagonizza tutti gli oppioidi; la buprenorfina, molto legata al recettore, richiede dosi più alte.",inf:"Dopo la somministrazione sorvegliare a lungo: dura meno della maggior parte degli oppioidi (ri-narcotizzazione). Rivalutare l'analgesia."},["oppioidi","recettorimu","antagonista","rinarcotizzazione"]],
["buprenorfina","Buprenorfina","Farmaco",["buprenorfina"],{pa:"Buprenorfina.",cl:"Oppioide agonista parziale dei recettori μ.",mec:"Si lega molto saldamente al recettore μ ma lo attiva solo in parte: effetto analgesico con un tetto per la depressione respiratoria.",ind:"Dolore cronico (cerotti), terapia della dipendenza da oppioidi.",vie:"Sublinguale, transdermica, EV.",av:"Nausea, sedazione, stipsi; depressione respiratoria soprattutto con benzodiazepine.",int:"Con benzodiazepine e alcol: rischio respiratorio. Può scatenare astinenza in chi assume altri oppioidi.",inf:"Il naloxone la antagonizza con difficoltà: possono servire dosi alte."},["agonistaparziale","naloxone"]],
["doxapram","Doxapram","Farmaco",["doxapram"],{pa:"Doxapram.",cl:"Stimolante respiratorio.",mec:"Stimola i chemocettori periferici e i centri respiratori del tronco encefalico.",ind:"Uso ormai raro, in casi selezionati di insufficienza respiratoria quando la ventilazione non invasiva non è disponibile.",vie:"EV in infusione.",av:"Ipertensione, tachicardia, agitazione, convulsioni.",int:"Con IMAO e simpaticomimetici: ipertensione.",inf:"Monitoraggio stretto di PA e stato neurologico."},["chemocettori"]],
["adrenalina","Adrenalina","Farmaco",["adrenalina"],{pa:"Adrenalina (epinefrina), soluzione 1 mg/mL (1:1000) per uso IM.",cl:"Catecolamina, agonista dei recettori α e β.",mec:"α1: vasocostrizione, aumento della pressione, riduzione dell'edema. β1: aumento di forza e frequenza del cuore. β2: broncodilatazione e riduzione del rilascio di mediatori dai mastociti.",ind:"Anafilassi (prima linea), arresto cardiaco, shock refrattario in infusione.",vie:"Anafilassi nell'adulto: 0,5 mg IM (0,5 mL di 1 mg/mL) nella coscia anterolaterale, ripetibile dopo 5 minuti. Arresto cardiaco: 1 mg EV. Infusione EV titolata solo in area critica.",av:"Tachicardia, palpitazioni, ipertensione, aritmie, ischemia miocardica, ansia, tremore, pallore.",int:"Betabloccanti ne riducono l'effetto (può servire glucagone). Antidepressivi triciclici e IMAO ne aumentano gli effetti cardiovascolari.",inf:"Nell'anafilassi non ritardarla mai per altri farmaci. Conoscere la differenza tra la dose IM e quella dell'arresto: lo scambio è un errore grave."},["anafilassi","recettoria1","recettorib1","recettorib2","vastolaterale","intramuscolo"]],
["clorfenamina","Clorfenamina","Farmaco",["clorfenamina"],{pa:"Clorfenamina maleato.",cl:"Antistaminico anti-H1 di prima generazione.",mec:"Blocca i recettori H1 dell'istamina: riduce prurito, orticaria e rinite.",ind:"Reazioni allergiche cutanee, sintomi cutanei dopo stabilizzazione di un'anafilassi.",vie:"Per os, IM o EV lenta.",av:"Sonnolenza, secchezza delle fauci, ritenzione urinaria, ipotensione se EV rapida.",int:"Con altri sedativi e alcol: sedazione aumentata.",inf:"Non tratta lo shock né l'edema delle vie aeree: nell'anafilassi non sostituisce l'adrenalina."},["antistaminici","istamina"]],
["cetirizina","Cetirizina","Farmaco",["cetirizina"],{pa:"Cetirizina dicloridrato.",cl:"Antistaminico anti-H1 di seconda generazione.",mec:"Blocca i recettori H1 periferici, con poca sedazione.",ind:"Rinite allergica, orticaria.",vie:"Per os, 10 mg una volta al giorno.",av:"Lieve sonnolenza, cefalea.",int:"Alcol e sedativi possono aumentare la sonnolenza.",inf:"Non è un farmaco d'emergenza."},["antistaminici"]],
["antistaminici","Antistaminici","Classe di farmaci",["antistaminic[oi]"],{d:"Farmaci che bloccano i recettori dell'istamina. Gli anti-H1 (clorfenamina, cetirizina) si usano nelle allergie; gli anti-H2 (famotidina) riducono l'acidità gastrica.",ap:"Nell'anafilassi trattano prurito e orticaria, ma non salvano la vita: lo fa l'adrenalina."},["clorfenamina","cetirizina","istamina"]],
["idrocortisone","Idrocortisone","Farmaco",["idrocortisone","cortisone","corticosteroid[ie]"],{pa:"Idrocortisone (sodio succinato per uso EV).",cl:"Corticosteroide.",mec:"Riduce la produzione di mediatori dell'infiammazione modificando l'espressione dei geni. L'effetto inizia dopo ore.",ind:"Insufficienza surrenalica, asma grave, prevenzione di sintomi prolungati dopo anafilassi (utilità discussa), shock settico refrattario.",vie:"EV, IM, per os.",av:"Iperglicemia, ritenzione di sodio, ipokaliemia, agitazione, aumento del rischio di infezioni con l'uso prolungato.",int:"Con insulina e antidiabetici: ne riduce l'effetto. Con diuretici: più ipokaliemia. Con FANS: più rischio di ulcera.",inf:"Controllare la glicemia. Non è un farmaco d'urgenza per lo shock anafilattico."},["anafilassi"]],
["amoxiclav","Amoxicillina-clavulanato","Farmaco",["amoxicillina-clavulanato","amoxicillina"],{pa:"Amoxicillina + acido clavulanico.",cl:"Antibiotico beta-lattamico (penicillina) con inibitore delle beta-lattamasi.",mec:"L'amoxicillina blocca la sintesi della parete batterica. Il clavulanato impedisce ai batteri di distruggerla con le loro beta-lattamasi.",ind:"Infezioni di cute, vie respiratorie, vie urinarie, cavo orale.",vie:"Per os o EV (es. 2,2 g EV ogni 8 ore).",av:"Diarrea, colite da Clostridioides difficile, rash, reazioni allergiche fino all'anafilassi, danno epatico.",int:"Con warfarin: può aumentarne l'effetto. Con metotrexato: ne aumenta la tossicità.",inf:"Prima della prima dose chiedere attivamente di reazioni pregresse a qualsiasi antibiotico, anche nell'infanzia. Osservare il paziente nei primi minuti dell'infusione."},["anafilassi","cefalosporine","antibiotico"]],
["cefalosporine","Cefalosporine","Classe di farmaci",["cefalosporin[ae]"],{d:"Antibiotici beta-lattamici simili alle penicilline (cefazolina, ceftriaxone, cefepime).",ap:"Esiste una reattività crociata con le penicilline, legata soprattutto alla somiglianza delle catene laterali. Dopo un'anafilassi da penicillina la scelta spetta al medico, a volte dopo valutazione allergologica."},["amoxiclav","anafilassi"]],
["antibiotico","Antibiotico","Classe di farmaci",["antibiotic[oi]"],{d:"Farmaco che uccide i batteri o ne blocca la crescita.",ap:"Nella sepsi va iniziato presto (entro un'ora nei casi gravi), ad ampio spettro, dopo aver prelevato le colture se questo non lo ritarda. Poi si adatta in base all'antibiogramma."},["sepsi","emocolture","antibiogramma"]],
["metformina","Metformina","Farmaco",["metformina"],{pa:"Metformina cloridrato.",cl:"Antidiabetico orale, biguanide.",mec:"Riduce la produzione di glucosio da parte del fegato e migliora la sensibilità all'insulina. Da sola raramente dà ipoglicemia.",ind:"Diabete tipo 2, farmaco di prima scelta.",vie:"Per os, durante o dopo i pasti.",av:"Disturbi gastrointestinali, carenza di vitamina B12, acidosi lattica (rara) in insufficienza renale grave, disidratazione, shock, ipossia.",int:"Mezzi di contrasto iodati: spesso sospesa prima e dopo l'esame. Alcol: più rischio di acidosi lattica.",inf:"Sospendere secondo indicazione medica in caso di disidratazione, sepsi, digiuno prolungato o insufficienza renale acuta. Non si somministra per bocca se la deglutizione non è stata valutata."},["diabete","lattati"]],
["calciogluconato","Calcio gluconato","Farmaco",["calcio gluconato"],{pa:"Calcio gluconato 10%.",cl:"Sale di calcio.",mec:"Nell'iperkaliemia rende più stabile la membrana delle cellule cardiache, riportando la differenza tra potenziale di riposo e soglia: protegge dalle aritmie in pochi minuti, senza abbassare il potassio.",ind:"Iperkaliemia con alterazioni ECG o K⁺ molto alto, ipocalcemia sintomatica, sovradosaggio di calcio-antagonisti.",vie:"EV lenta: nell'iperkaliemia dell'adulto 30 mL di soluzione al 10% in 5-10 minuti, ripetibile. Vena di buon calibro.",av:"Bradicardia se infuso rapidamente, danno tissutale se stravasa, sensazione di calore.",int:"Con digossina: rischio di aritmie (usare con cautela). Precipita con bicarbonato e fosfati nella stessa linea.",inf:"Monitoraggio ECG durante e dopo. Controllare l'accesso venoso. L'effetto dura 30-60 minuti."},["iperkaliemia","potenzialeriposo","ecg"]],
["nitroglicerina","Nitroglicerina","Farmaco",["nitroglicerina"],{pa:"Nitroglicerina (glicerile trinitrato).",cl:"Nitrato, vasodilatatore.",mec:"Libera ossido nitrico: dilata soprattutto le vene (riduce il precarico) e, a dosi più alte, le arterie (riduce il postcarico). Dilata anche le coronarie.",ind:"Angina, edema polmonare acuto con PA conservata, scompenso acuto ipertensivo.",vie:"Sublinguale (spray o compresse), EV in infusione, transdermica.",av:"Cefalea, ipotensione, tachicardia riflessa, capogiri.",int:"Con sildenafil, tadalafil e simili: ipotensione grave, controindicazione assoluta. Con altri antipertensivi: effetto additivo.",inf:"Misurare la PA prima: non si dà con sistolica bassa. Controindicata o molto pericolosa nella stenosi aortica severa e nell'infarto del ventricolo destro, situazioni in cui la gittata dipende dal precarico."},["precarico","stenosiaortica","angina","ossidonitrico"]],
["bicarbonato","Bicarbonato di sodio","Farmaco · Parametro",["bicarbonato di sodio","bicarbonato","hco₃⁻","hco3"],{d:"Il bicarbonato (HCO₃⁻) è il principale tampone del sangue: neutralizza gli acidi. All'emogasanalisi è un indicatore metabolico.",val:"HCO₃⁻ 22-26 mmol/L.",ap:"Alto: alcalosi metabolica o compenso renale di un'acidosi respiratoria cronica (come nella BPCO). Basso: acidosi metabolica (chetoacidosi, acidosi lattica). Come farmaco EV si usa in casi selezionati; può causare ipokaliemia, sovraccarico di sodio e necrosi se stravasa."},["emogasanalisi","ph","acidosi"]],
["resine","Resine leganti il potassio","Classe di farmaci",["resine leganti","patiromer"],{d:"Farmaci che legano il potassio nell'intestino e lo eliminano con le feci: patiromer, sodio zirconio ciclosilicato, sodio polistirene sulfonato.",ap:"Agiscono in ore: non sono il trattamento immediato dell'iperkaliemia grave. Possono dare stipsi e alterazioni di magnesio e sodio."},["iperkaliemia"]],
["rifampicina","Rifampicina","Farmaco",["rifampicina"],{pa:"Rifampicina.",cl:"Antibiotico rifamicinico.",mec:"Blocca l'RNA polimerasi batterica.",ind:"Tubercolosi, alcune infezioni da stafilococco su protesi, profilassi della meningite meningococcica.",vie:"Per os o EV.",av:"Colorazione arancio-rossa di urine, lacrime e sudore (innocua), danno epatico.",int:"Potente induttore enzimatico: riduce l'effetto di anticoagulanti orali, contraccettivi orali, molti antiretrovirali, cortisone.",inf:"Avvisare il paziente della colorazione delle urine. Può rovinare le lenti a contatto morbide."},[]],
["cristalloidi","Cristalloidi","Farmaco",["cristalloid[ie]","fisiologica","soluzione fisiologica","nacl 0,9%"],{pa:"Soluzioni di acqua ed elettroliti: fisiologica (NaCl 0,9%), Ringer lattato, soluzioni bilanciate.",cl:"Liquidi per infusione EV.",mec:"Espandono il volume del sangue; una parte passa rapidamente nei tessuti.",ind:"Ipovolemia, shock (settico, anafilattico, emorragico in attesa di sangue), disidratazione, chetoacidosi.",vie:"EV in bolo o infusione, secondo prescrizione (nella sepsi con ipotensione almeno 30 mL/kg nelle prime 3 ore).",av:"Sovraccarico di liquidi ed edema, acidosi ipercloremica con grandi volumi di fisiologica.",int:"Incompatibilità specifiche con alcuni farmaci nella stessa linea.",inf:"Rivalutare dopo ogni bolo: PA, FC, diuresi, respiro, crepitii. Nel paziente cardiopatico attenzione al sovraccarico."},["sepsi","shock","glucosata"]],
["glucosata","Soluzione glucosata 5%","Farmaco",["glucosata"],{pa:"Glucosio al 5% in acqua.",cl:"Soluzione isotonica che, una volta metabolizzato il glucosio, si comporta come acqua libera.",mec:"Apporta acqua e poche calorie.",ind:"Mantenimento idrico, aggiunta all'infusione di insulina quando la glicemia scende (chetoacidosi), diluizione di farmaci.",vie:"EV.",av:"Iponatriemia se usata in grandi quantità, iperglicemia.",int:"Incompatibile con alcuni farmaci (es. fenitoina).",inf:"Non si usa per la rianimazione volemica iniziale."},["chetoacidosi","cristalloidi"]],
["ossigeno","Ossigeno","Farmaco",["ossigeno","o₂","ossigenoterapia"],{pa:"Ossigeno medicale.",cl:"Gas medicinale.",mec:"Aumenta la frazione di ossigeno inspirata (FiO₂) e quindi l'ossigeno disponibile per l'emoglobina.",ind:"Ipossiemia. Non serve se la saturazione è nel range.",vie:"Occhialini nasali, maschera semplice, maschera Venturi, maschera con reservoir, alti flussi nasali, ventilazione.",av:"Ipercapnia nei pazienti a rischio (BPCO, obesità grave, malattie neuromuscolari), secchezza delle mucose, danno polmonare a concentrazioni alte prolungate. Infiammabile.",int:"—",inf:"È un farmaco: va prescritto con un obiettivo di saturazione (94-98% o 88-92% nei pazienti a rischio ipercapnico). In emergenza si avvia secondo protocollo e si fa prescrivere subito."},["fio2","saturazione","venturi","ipercapnia","ipossiemia"]],
["emazie","Emazie concentrate","Emocomponente",["emazie concentrate"],{d:"Unità di globuli rossi separati dal sangue di un donatore, con pochissimo plasma, conservati a 2-6°C.",ap:"Un'unità alza l'emoglobina di circa 1 g/dL nell'adulto. Va trasfusa entro 4 ore dall'uscita dalla frigoemoteca, attraverso un deflussore con filtro dedicato, senza aggiungere farmaci nella stessa linea."},["trasfusione","gruppoabo","reazioneemolitica"]],
["alteplase","Trombolisi","Procedura · Farmaco",["trombolisi","trombolitic[oi]"],{d:"Somministrazione di un farmaco che scioglie il trombo attivando la plasmina, l'enzima che degrada la fibrina. Nell'ictus si usano alteplase o tenecteplase EV.",ap:"Nell'ictus ischemico si valuta in genere entro 4,5 ore dall'ultimo momento noto in benessere, dopo che la TC ha escluso un'emorragia e con PA sotto 185/110 mmHg. Rischio principale: emorragia, anche cerebrale. Dopo l'infusione si controllano spesso parametri e stato neurologico, e per 24 ore si evitano antiaggreganti e anticoagulanti."},["ictus","penombra","tc","lkw"]],
["sostitutosale","Sostituto del sale","Prodotto",["sostituto del sale"],{d:"Prodotto da usare al posto del sale da cucina, che contiene cloruro di potassio invece di (o insieme a) cloruro di sodio.",ap:"Pericoloso in insufficienza renale e con ACE-inibitori, sartani, spironolattone: può causare iperkaliemia grave."},["iperkaliemia","ramipril"]],

/* ---------- ENDOCRINO E METABOLISMO ---------- */
["diabete","Diabete mellito","Clinica",["diabete","diabetic[oa]"],{d:"Malattia caratterizzata da glicemia cronicamente alta. Tipo 1: distruzione autoimmune delle cellule beta, serve insulina dall'esordio. Tipo 2: resistenza all'insulina con progressivo esaurimento delle cellule beta.",ap:"Complicanze acute: ipoglicemia (da terapia), chetoacidosi (soprattutto tipo 1), stato iperosmolare (soprattutto tipo 2). Complicanze croniche: retinopatia, nefropatia, neuropatia, malattia cardiovascolare."},["insulina","ipoglicemia","chetoacidosi","glicemia"]],
["basalbolus","Schema basal-bolus","Terapia",["basal-bolus"],{d:"Schema insulinico con una insulina lenta (basale) che copre il bisogno di fondo e insuline rapide (bolo) ai pasti.",ap:"Imita la secrezione fisiologica. La basale non si salta nemmeno se il paziente non mangia; i boli si adattano al pasto."},["glargine","lispro"]],
["glicemia","Glicemia","Parametro",["glicemi[ae]","glicemia capillare"],{d:"Concentrazione di glucosio nel sangue.",val:"A digiuno 70-99 mg/dL. In ospedale, nel paziente diabetico, obiettivo spesso 140-180 mg/dL.",ap:"La glicemia capillare si misura con glucometro da una goccia di sangue del polpastrello (lato del dito, dopo aver lavato le mani)."},["ipoglicemia","diabete"]],
["ipoglicemia","Ipoglicemia","Clinica",["ipoglicemi[ae]"],{d:"Glicemia troppo bassa: sotto 70 mg/dL è un livello d'allerta, sotto 54 mg/dL è clinicamente significativa; si dice grave quando la persona ha bisogno di aiuto per correggerla.",ap:"Sintomi adrenergici (sudore, tremore, tachicardia, fame, ansia) e neuroglicopenici (confusione, sonnolenza, disturbi visivi, convulsioni, coma). Trattamento nel paziente cosciente: regola del 15. Cause frequenti: insulina senza pasto, errori di dose, insufficienza renale, alcol, esercizio."},["regola15","glucagone","sintomiadrenergici","neuroglicopenici"]],
["regola15","Regola del 15","Procedura",["regola del 15"],{d:"Protocollo per l'ipoglicemia nel paziente cosciente: 15 g di zuccheri semplici, glicemia dopo 15 minuti, ripetere se ancora sotto 70 mg/dL.",ap:"15 g corrispondono circa a 150 mL di succo o bibita zuccherata, 3 zollette o 3-4 compresse di glucosio, un cucchiaio di miele. Superati i 70 mg/dL, se il pasto è lontano, si dà uno spuntino con carboidrati complessi."},["ipoglicemia"]],
["sintomiadrenergici","Sintomi adrenergici","Segno",["adrenergic[io]"],{d:"Sintomi dovuti alla scarica di adrenalina e noradrenalina: sudorazione, tremore, tachicardia, palpitazioni, ansia, fame, pallore.",ap:"Nell'ipoglicemia sono l'allarme precoce. Possono mancare in chi assume betabloccanti o ha ipoglicemie frequenti (ipoglicemia non avvertita)."},["ipoglicemia","adrenalina","betabloccanti"]],
["neuroglicopenici","Sintomi neuroglicopenici","Segno",["neuroglicopenic[io]"],{d:"Sintomi dovuti al cervello che riceve troppo poco glucosio: confusione, difficoltà a concentrarsi, comportamento strano, visione offuscata, sonnolenza, convulsioni, coma.",ap:"Indicano un'ipoglicemia già importante. Sono una delle ragioni per cui un'ipoglicemia può simulare un ictus."},["ipoglicemia"]],
["chetoacidosi","Chetoacidosi diabetica","Clinica",["chetoacidosi"],{d:"Emergenza dovuta alla mancanza di insulina: il corpo brucia i grassi e produce corpi chetonici acidi, il sangue diventa acido.",val:"Criteri tipici: chetonemia ≥ 3 mmol/L, pH < 7,3 o bicarbonato < 15-18 mmol/L, di solito glicemia > 250 mg/dL.",ap:"Segni: poliuria, sete, vomito, dolore addominale, disidratazione, respiro di Kussmaul, alito acetonemico, sonnolenza. Terapia: liquidi, potassio, insulina in infusione, poi glucosio quando la glicemia scende. Risolta quando chetoni e pH tornano nei limiti."},["chetoni","kussmaul","diuresiosmotica","potassio","insulina"]],
["chetoni","Corpi chetonici","Fisiologia",["chetoni","chetonemia","corpi chetonici","chetonic[io]"],{d:"Molecole prodotte dal fegato a partire dagli acidi grassi quando manca il glucosio utilizzabile: acetoacetato, beta-idrossibutirrato, acetone.",val:"Chetonemia capillare: < 0,6 mmol/L normale; 0,6-1,5 da sorvegliare; 1,5-3 rischio di chetoacidosi; > 3 chetoacidosi probabile.",ap:"Sono acidi: in eccesso causano acidosi metabolica. L'acetone viene eliminato con il respiro (alito fruttato)."},["chetoacidosi","acetone"]],
["acetone","Acetone","Fisiologia",["acetone"],{d:"Il più volatile dei corpi chetonici. Viene eliminato con il respiro e dà all'alito un odore dolciastro, di frutta matura o di smalto.",ap:"È un segno clinico utile di chetosi."},["chetoni"]],
["diuresiosmotica","Diuresi osmotica","Fisiologia",["diuresi osmotica"],{d:"Aumento della produzione di urina dovuto a sostanze che restano nel tubulo renale e trattengono acqua.",ap:"Nell'iperglicemia il glucosio supera la capacità del rene di riassorbirlo (soglia circa 180 mg/dL), passa nelle urine e trascina acqua e sali: poliuria, sete, disidratazione, perdita di potassio."},["poliuria","chetoacidosi"]],
["poliuria","Poliuria","Segno",["poliuria"],{d:"Produzione di urina eccessiva, in genere più di 3 litri al giorno nell'adulto.",ap:"Cause: iperglicemia, diuretici, diabete insipido, eccesso di liquidi, fase di recupero di un danno renale."},["diuresiosmotica"]],
["pancreas","Pancreas","Anatomia",["pancreas","pancreatic[oa]"],{d:"Ghiandola retroperitoneale dietro lo stomaco, divisa in testa (nell'ansa del duodeno), corpo e coda (verso la milza).",ap:"Parte esocrina (acini, circa il 98%): produce enzimi digestivi versati nel duodeno dal dotto di Wirsung. Parte endocrina (isole di Langerhans): produce insulina, glucagone, somatostatina."},["langerhans","acini","wirsung"]],
["langerhans","Isole di Langerhans","Anatomia",["isole di langerhans"],{d:"Piccoli gruppi di cellule endocrine sparsi nel pancreas, circa l'1-2% della ghiandola, molto vascolarizzati.",ap:"Cellule alfa (glucagone), beta (insulina, le più numerose), delta (somatostatina), PP (polipeptide pancreatico)."},["cellulealfa","cellulebeta","celluledelta","pancreas"]],
["cellulealfa","Cellule alfa","Anatomia",["cellule alfa"],{d:"Cellule delle isole di Langerhans che producono glucagone, soprattutto alla periferia dell'isola.",ap:"Si attivano quando la glicemia scende, con lo stimolo simpatico e con alcuni aminoacidi."},["glucagone","langerhans"]],
["cellulebeta","Cellule beta","Anatomia",["cellule beta"],{d:"Cellule delle isole di Langerhans che producono insulina; sono le più numerose.",ap:"Sentono la glicemia tramite il trasportatore GLUT2. Nel diabete tipo 1 sono distrutte da un processo autoimmune."},["insulina","glut","langerhans"]],
["celluledelta","Cellule delta","Anatomia",["cellule delta"],{d:"Cellule delle isole di Langerhans che producono somatostatina.",ap:"La somatostatina frena la secrezione di insulina e glucagone e rallenta la digestione."},["somatostatina"]],
["somatostatina","Somatostatina","Ormone",["somatostatina"],{d:"Ormone inibitore prodotto dalle cellule delta del pancreas, dall'ipotalamo e dall'intestino.",ap:"Inibisce GH, insulina, glucagone e molte secrezioni digestive. Il suo analogo octreotide si usa ad esempio nel sanguinamento da varici esofagee."},["celluledelta"]],
["glut","GLUT (trasportatori del glucosio)","Fisiologia",["glut2","glut"],{d:"Proteine di membrana che fanno entrare il glucosio nelle cellule.",ap:"GLUT2 (fegato, cellule beta): sempre attivo, permette alle beta di sentire la glicemia. GLUT4 (muscolo, tessuto adiposo): viene portato in membrana dall'insulina."},["insulina","cellulebeta"]],
["acini","Acini pancreatici","Anatomia",["acin[io]","cellule acinose"],{d:"Unità secretorie della parte esocrina del pancreas.",ap:"Producono enzimi digestivi (amilasi, lipasi, proteasi) che, attraverso i dotti, arrivano al duodeno."},["pancreas","wirsung"]],
["wirsung","Dotto di Wirsung","Anatomia",["dotto di wirsung","wirsung"],{d:"Dotto pancreatico principale: percorre la ghiandola dalla coda alla testa.",ap:"Si unisce al coledoco e sbocca nel duodeno alla papilla di Vater, controllata dallo sfintere di Oddi."},["pancreas"]],
["glicogenolisi","Glicogenolisi","Fisiologia",["glicogenolisi","glicogeno"],{d:"Demolizione del glicogeno, la riserva di glucosio di fegato e muscoli.",ap:"Il fegato libera il glucosio nel sangue; il muscolo lo usa solo per sé. È stimolata da glucagone e adrenalina."},["glucagone","gluconeogenesi"]],
["gluconeogenesi","Gluconeogenesi","Fisiologia",["gluconeogenesi"],{d:"Produzione di nuovo glucosio da molecole non zuccherine (lattato, aminoacidi, glicerolo), soprattutto nel fegato e in parte nel rene.",ap:"Diventa la fonte principale di glucosio nel digiuno prolungato. Stimolata da glucagone e cortisolo."},["glicogenolisi","glucagone"]],

["pa","Pressione arteriosa (PA)","Parametro",["!PA","pressione arteriosa","sistolica","diastolica","!PAS"],{d:"Pressione del sangue nelle arterie. Si scrive sistolica/diastolica in mmHg: la sistolica è il picco durante la contrazione del cuore, la diastolica il valore minimo durante il rilasciamento.",val:"Ottimale sotto 120/80 mmHg; ipertensione da 140/90 mmHg in su (misurazioni ripetute).",ap:"Si misura con bracciale della misura giusta, braccio all'altezza del cuore, paziente a riposo. Non sul braccio della fistola per dialisi o dal lato di una dissezione linfonodale ascellare."},["pam","ipotensione","pressionedifferenziale"]],
["fc","Frequenza cardiaca (FC)","Parametro",["!FC","frequenza cardiaca"],{d:"Numero di battiti del cuore al minuto.",val:"Adulto a riposo 60-100 bpm.",ap:"Si valuta anche il ritmo (regolare o irregolare) e l'ampiezza del polso. Una FC alta è spesso un compenso: dolore, febbre, ipovolemia, ipossia, sepsi."},["tachicardia","bradicardia"]],
["fr","Frequenza respiratoria (FR)","Parametro",["!FR","frequenza respiratoria"],{d:"Numero di atti respiratori al minuto.",val:"Adulto a riposo 12-20 atti al minuto.",ap:"Va contata per un minuto intero, senza che il paziente se ne accorga. È il parametro più spesso trascurato e uno dei più precoci nel segnalare un peggioramento."},["tachipnea","depressionerespiratoria","news2"]],
["temperatura","Temperatura corporea","Parametro",["temperatura","timpanica"],{d:"Misura del calore del corpo.",val:"Circa 36-37,5°C.",ap:"Sedi: timpanica, ascellare, orale, rettale, cutanea (meno precisa). Sotto 35°C si parla di ipotermia."},["febbre"]],
/* ---------- CUORE E CIRCOLO ---------- */
["scompenso","Scompenso cardiaco","Clinica",["scompenso cardiaco","scompenso","scompensat[oa]"],{d:"Condizione in cui il cuore non riesce a pompare abbastanza sangue per le necessità del corpo, o ci riesce solo a pressioni di riempimento troppo alte.",ap:"Si classifica in base alla frazione d'eiezione: ridotta (≤ 40%), lievemente ridotta (41-49%), conservata (≥ 50%). Riacutizzazioni tipiche dopo eccesso di sale, terapia saltata, infezioni, aritmie. Sintomi: dispnea, ortopnea, edemi, aumento di peso, stanchezza."},["frazioneeiezione","edemapolmonare","ortopnea","precarico"]],
["edemapolmonare","Edema polmonare acuto","Clinica",["edema polmonare"],{d:"Accumulo improvviso di liquido negli alveoli polmonari, che impedisce lo scambio dei gas.",ap:"Cardiogeno: per aumento della pressione nei capillari polmonari (scompenso, crisi ipertensiva, valvulopatie, ischemia). Non cardiogeno: per danno della membrana (ARDS). Segni: dispnea grave, ortopnea, crepitii, espettorato schiumoso rosato, ipossiemia, sudorazione."},["crepitii","starling","ards","scompenso","furosemide"]],
["crepitii","Crepitii","Segno",["crepiti[io]"],{d:"Rumori polmonari discontinui, brevi, udibili soprattutto in inspirazione, simili al rumore dei capelli strofinati vicino all'orecchio.",ap:"Fini: liquido o riapertura di alveoli (edema polmonare, fibrosi). Grossolani: secrezioni nelle vie aeree (bronchite, polmonite). Nell'edema cardiogeno sono bilaterali e partono dalle basi."},["edemapolmonare","sibili"]],
["sibili","Sibili","Segno",["sibil[io]"],{d:"Rumori polmonari continui, musicali, soprattutto in espirazione, dovuti al passaggio d'aria in vie aeree ristrette.",ap:"Tipici di asma, BPCO, anafilassi. Possono comparire anche nell'edema polmonare (asma cardiaco). Un torace silente in un asmatico grave è più preoccupante dei sibili."},["broncospasmo","asma","bpco"]],
["giugulari","Giugulari turgide","Segno",["giugulari"],{d:"Vene giugulari distese e visibili sul collo con il paziente semiseduto a 45°.",ap:"Indicano pressione alta nell'atrio destro: scompenso, sovraccarico di liquidi, embolia polmonare massiva, tamponamento, pneumotorace iperteso."},["scompenso"]],
["ortopnea","Ortopnea","Segno",["ortopnea"],{d:"Dispnea che compare da sdraiati e migliora da seduti.",ap:"Da sdraiati arriva più sangue al cuore e ai polmoni e il diaframma è spinto in alto. Si quantifica chiedendo con quanti cuscini dorme il paziente."},["scompenso","precarico"]],
["precarico","Precarico","Fisiologia",["precarico"],{d:"Grado di riempimento (e quindi di stiramento) del ventricolo alla fine della diastole.",ap:"Secondo la legge di Frank-Starling, più il ventricolo si riempie, più forte si contrae, entro certi limiti. Aumenta con liquidi, gambe sollevate, posizione supina; diminuisce con diuretici, nitrati, emorragia, posizione seduta con gambe giù."},["postcarico","gittata","frankstarling"]],
["frankstarling","Legge di Frank-Starling","Fisiologia",["frank-starling"],{d:"Il cuore espelle più sangue quanto più è stato riempito in diastole.",ap:"Le fibre più stirate si contraggono con più forza. Un ventricolo rigido o una valvola stretta riducono la possibilità di sfruttare questo meccanismo."},["precarico"]],
["postcarico","Postcarico","Fisiologia",["postcarico"],{d:"La resistenza che il ventricolo deve vincere per espellere il sangue.",ap:"Per il ventricolo sinistro dipende dalla pressione arteriosa e dalla valvola aortica: una stenosi aortica aumenta molto il postcarico."},["precarico","stenosiaortica"]],
["gittata","Gittata sistolica","Fisiologia",["gittata"],{d:"Volume di sangue espulso dal ventricolo a ogni battito.",val:"Circa 60-100 mL nell'adulto.",ap:"Gittata = volume telediastolico − volume telesistolico. Moltiplicata per la frequenza dà la portata cardiaca (circa 5 L/min a riposo)."},["precarico","frazioneeiezione"]],
["frazioneeiezione","Frazione d'eiezione","Parametro",["frazione d'eiezione"],{d:"Percentuale del sangue contenuto nel ventricolo a fine diastole che viene espulsa a ogni battito.",val:"Normale ≥ 50-55%.",ap:"Si misura con l'ecocardiogramma. Una FE conservata non esclude lo scompenso: il ventricolo può essere rigido e riempirsi male."},["scompenso","ecocardiogramma"]],
["looppv","Loop pressione-volume","Fisiologia",["loop pressione-volume"],{d:"Grafico che descrive un ciclo cardiaco mettendo in relazione il volume del ventricolo (asse orizzontale) e la sua pressione (asse verticale).",ap:"Quattro fasi: riempimento, contrazione isovolumetrica, eiezione, rilasciamento isovolumetrico. L'area del loop rappresenta il lavoro del cuore. Nella stenosi aortica il picco di pressione è molto alto; con poco precarico il loop si stringe e si sposta a sinistra."},["precarico","gittata","stenosiaortica"]],
["stenosiaortica","Stenosi aortica","Clinica",["stenosi aortica"],{d:"Restringimento della valvola aortica che ostacola l'uscita del sangue dal ventricolo sinistro.",ap:"Nell'anziano è quasi sempre degenerativa calcifica. Il ventricolo si ispessisce (ipertrofia) e diventa rigido. Sintomi classici: dispnea da sforzo, angina, sincope. Severa: area valvolare < 1 cm², gradiente medio ≥ 40 mmHg. La gittata dipende dal precarico: diuretici e vasodilatatori vanno usati con molta cautela. Trattamento: sostituzione valvolare (TAVI o chirurgica)."},["soffio","tavi","sincope","precarico","nitroglicerina"]],
["insuffmitralica","Insufficienza mitralica","Clinica",["insufficienza mitralica"],{d:"Chiusura incompleta della valvola mitrale: in sistole parte del sangue torna dal ventricolo all'atrio sinistro.",ap:"Soffio olosistolico all'apice irradiato all'ascella. Può dare dilatazione atriale, fibrillazione atriale, scompenso."},["soffio"]],
["insuffaortica","Insufficienza aortica","Clinica",["insufficienza aortica"],{d:"Chiusura incompleta della valvola aortica: in diastole il sangue torna dall'aorta al ventricolo sinistro.",ap:"Soffio diastolico in decrescendo al margine sternale sinistro, pressione differenziale ampia, polso scoccante."},["soffio","pressionedifferenziale"]],
["stenosimitralica","Stenosi mitralica","Clinica",["stenosi mitralica"],{d:"Restringimento della valvola mitrale che ostacola il passaggio di sangue dall'atrio al ventricolo sinistro.",ap:"Spesso esito di malattia reumatica. Rullio diastolico all'apice con schiocco d'apertura, fibrillazione atriale frequente."},["soffio"]],
["soffio","Soffio cardiaco","Segno",["soffi[oi]","focolaio aortico"],{d:"Rumore prodotto dal flusso turbolento del sangue attraverso valvole o cavità, udibile con lo stetoscopio.",ap:"Si descrive per fase (sistolico, diastolico), sede di massima intensità (focolai: aortico al 2° spazio intercostale destro, polmonare al 2° sinistro, tricuspidale al 4°-5° parasternale sinistro, mitralico all'apice), irradiazione e intensità. Un nuovo soffio va segnalato e approfondito con l'ecocardiogramma."},["stenosiaortica","ecocardiogramma"]],
["tavi","TAVI","Procedura",["!TAVI"],{d:"Impianto transcatetere di valvola aortica: una protesi montata su un catetere viene portata, di solito dall'arteria femorale, fino alla valvola malata e aperta al suo interno.",ap:"Alternativa alla cardiochirurgia, soprattutto in pazienti anziani o ad alto rischio. Dopo la procedura si controllano sito di accesso, polsi periferici, ritmo (rischio di blocchi atrioventricolari), stato neurologico."},["stenosiaortica","heartteam"]],
["heartteam","Heart Team","Organizzazione",["heart team"],{d:"Gruppo multidisciplinare (cardiologo clinico, cardiologo interventista, cardiochirurgo, anestesista, imaging, a volte geriatra e infermiere) che decide insieme il trattamento delle valvulopatie e della cardiopatia ischemica complessa."},["tavi"]],
["ecocardiogramma","Ecocardiogramma","Esame",["ecocardiogramma"],{d:"Ecografia del cuore: mostra cavità, pareti, valvole, flussi e frazione d'eiezione.",ap:"Transtoracico (sonda sul torace) o transesofageo (sonda nell'esofago, più dettagliato, richiede digiuno e sedazione)."},["frazioneeiezione","stenosiaortica"]],
["sincope","Sincope","Clinica",["sincope","svien[ei]","perde coscienza"],{d:"Perdita di coscienza transitoria, a inizio rapido e recupero spontaneo e completo, dovuta a una riduzione globale del flusso di sangue al cervello.",ap:"Riflessa (vasovagale), ortostatica (ipotensione nel passaggio in piedi, ad esempio da diuretici o disidratazione), cardiaca (aritmie, stenosi aortica): la cardiaca è la più pericolosa. Primo intervento: posizione supina, gambe sollevate, valutazione di respiro e polso."},["stenosiaortica","ipotensione"]],
["angina","Angina pectoris","Clinica",["angina"],{d:"Dolore o oppressione toracica dovuti a un apporto di ossigeno al miocardio insufficiente rispetto al bisogno.",ap:"Tipica: retrosternale, irradiata a braccio sinistro, collo o mandibola, scatenata dallo sforzo e ridotta dal riposo o dai nitrati. Può comparire anche nella stenosi aortica, per ipertrofia e alto consumo di ossigeno."},["nitroglicerina"]],
["ipertrofia","Ipertrofia ventricolare","Clinica",["ispessit[oa]","ipertrofi[ac]"],{d:"Aumento dello spessore della parete del ventricolo.",ap:"Risposta a un sovraccarico di pressione (ipertensione, stenosi aortica). Il ventricolo ispessito è più rigido, si riempie peggio e consuma più ossigeno."},["stenosiaortica"]],
["fibrillazioneatriale","Fibrillazione atriale","Clinica",["fibrillazione atriale","!FA"],{d:"Aritmia in cui gli atri si attivano in modo caotico e non si contraggono: il polso diventa irregolarmente irregolare.",ap:"Si perde il contributo della contrazione atriale al riempimento ventricolare. Il sangue ristagna nell'auricola sinistra e si possono formare trombi: per questo si usa l'anticoagulante (in base al punteggio CHA₂DS₂-VASc). All'ECG: onde P assenti, intervalli R-R irregolari."},["auricola","ictus","apixaban","ecg"]],
["fibrillazioneventricolare","Fibrillazione ventricolare","Clinica",["fibrillazione ventricolare"],{d:"Aritmia in cui i ventricoli si attivano in modo caotico e non pompano: è un arresto cardiaco.",ap:"All'ECG: onde irregolari senza complessi riconoscibili. Si tratta con rianimazione cardiopolmonare e defibrillazione immediata."},["asistolia","ecg"]],
["asistolia","Asistolia","Clinica",["asistolia"],{d:"Assenza di attività elettrica del cuore: linea piatta all'ECG. È un arresto cardiaco non defibrillabile.",ap:"Si tratta con rianimazione cardiopolmonare, adrenalina e ricerca delle cause reversibili (ipossia, ipovolemia, iper/ipokaliemia, ipotermia, trombosi, tamponamento, tossici, pneumotorace)."},["fibrillazioneventricolare"]],
["extrasistole","Battiti anticipati (extrasistoli)","Clinica",["battit[oi] anticipat[oi]","extrasistol[ei]"],{d:"Battiti che nascono prima del previsto da un punto diverso dal nodo del seno, negli atri o nei ventricoli.",ap:"Sono spesso innocui, ma se aumentano possono indicare ipokaliemia, ipomagnesiemia, ischemia o tossicità da farmaci."},["ipokaliemia","ecg"]],
["tachicardia","Tachicardia","Parametro",["tachicardi[ac]"],{d:"Frequenza cardiaca sopra 100 battiti al minuto nell'adulto a riposo.",ap:"Cause: febbre, dolore, ansia, ipovolemia, anemia, ipossia, sepsi, ipoglicemia, farmaci, aritmie. È spesso un compenso: va cercata la causa."},["bradicardia"]],
["bradicardia","Bradicardia","Parametro",["bradicardi[ac]"],{d:"Frequenza cardiaca sotto 60 battiti al minuto (spesso si considera significativa sotto 50).",ap:"Può essere normale negli sportivi. Cause: betabloccanti, iperkaliemia, ipotermia, ipotiroidismo, blocchi della conduzione, aumento della pressione intracranica."},["tachicardia","iperkaliemia"]],
["auricola","Auricola sinistra","Anatomia",["auricola"],{d:"Piccola estroflessione a sacco dell'atrio sinistro.",ap:"Nella fibrillazione atriale il sangue vi ristagna: è la sede più frequente dei trombi che poi causano ictus. Può essere chiusa con un dispositivo percutaneo in chi non può assumere anticoagulanti."},["fibrillazioneatriale","ictus"]],
["ipotensione","Ipotensione","Parametro",["ipotensione","ipotes[oa]"],{d:"Pressione arteriosa troppo bassa per garantire la perfusione degli organi; spesso si usa il riferimento di una sistolica < 90 mmHg o di una PAM < 65 mmHg.",ap:"Segni di scarsa perfusione: confusione, cute fredda e marezzata, oliguria, aumento dei lattati, tempo di riempimento capillare lungo."},["pam","shock"]],
["pam","Pressione arteriosa media (PAM)","Parametro",["pressione arteriosa media","!PAM"],{d:"Pressione media nelle arterie durante l'intero ciclo cardiaco: è quella che perfonde gli organi.",val:"PAM ≈ (sistolica + 2 × diastolica) / 3. Normale circa 70-100 mmHg; obiettivo minimo nello shock: 65 mmHg.",ap:"La diastolica pesa il doppio perché il cuore passa circa due terzi del ciclo in diastole."},["ipotensione","pressionedifferenziale"]],
["pressionedifferenziale","Pressione differenziale","Parametro",["differenziale"],{d:"Differenza tra pressione sistolica e diastolica.",val:"Normale circa 40 mmHg.",ap:"Ampia: rigidità arteriosa dell'anziano, insufficienza aortica, sepsi iniziale. Ridotta: shock con bassa gittata, tamponamento, stenosi aortica severa."},["pam"]],
["shock","Shock","Clinica",["shock"],{d:"Insufficienza circolatoria acuta: l'ossigeno che arriva ai tessuti non basta per il loro bisogno.",ap:"Tipi: ipovolemico (emorragia, disidratazione), cardiogeno (il cuore non pompa), distributivo (vasi dilatati: sepsi, anafilassi, causa neurologica), ostruttivo (embolia polmonare, tamponamento, pneumotorace iperteso). Segni: ipotensione, tachicardia, cute fredda o marezzata, confusione, oliguria, lattati alti."},["shockdistributivo","sepsi","anafilassi","lattati"]],
["shockdistributivo","Shock distributivo","Clinica",["shock distributivo"],{d:"Shock dovuto a una dilatazione eccessiva dei vasi e a perdita di liquido dai capillari: il volume di sangue c'è, ma è distribuito male.",ap:"Esempi: shock settico, anafilattico, neurogeno. Spesso la cute all'inizio è calda e arrossata."},["shock","sepsi","anafilassi","ossidonitrico"]],
["ossidonitrico","Ossido nitrico","Fisiologia",["ossido nitrico"],{d:"Gas prodotto dall'endotelio che rilassa la muscolatura liscia dei vasi e li dilata.",ap:"Nella sepsi i mediatori infiammatori ne fanno produrre grandi quantità: vasodilatazione e ipotensione. È il meccanismo d'azione dei nitrati come la nitroglicerina."},["sepsi","nitroglicerina"]],
["vasocostrizione","Vasocostrizione","Fisiologia",["vasocostrizione"],{d:"Restringimento dei vasi per contrazione della loro muscolatura liscia.",ap:"Aumenta la resistenza e la pressione. Nel circolo polmonare l'ipossia provoca vasocostrizione (vasocostrizione ipossica), al contrario degli altri distretti."},["vasocostrizioneipossica","recettoria1"]],
["vasocostrizioneipossica","Vasocostrizione polmonare ipossica","Fisiologia",["vasocostrizione ipossica","vasocostrizione polmonare ipossica"],{d:"Riflesso per cui le arteriole polmonari si chiudono dove gli alveoli hanno poco ossigeno.",ap:"Devia il sangue verso gli alveoli ben ventilati e migliora il rapporto ventilazione/perfusione. Un eccesso di ossigeno lo annulla: è uno dei motivi per cui nella BPCO l'ossigeno ad alto flusso fa salire la CO₂."},["vq","ipercapnia","bpco"]],

["starling","Forze di Starling","Fisiologia",["forze di starling","starling"],{d:"Le forze che regolano il passaggio di liquido tra capillari e tessuti.",ap:"La pressione idrostatica (la spinta del sangue) tende a far uscire il liquido dal capillare; la pressione oncotica (dovuta soprattutto all'albumina) tende a trattenerlo. Un edema compare se aumenta la pressione idrostatica (scompenso), cala la pressione oncotica (ipoalbuminemia), aumenta la permeabilità (infiammazione, sepsi, ARDS) o si riduce il drenaggio linfatico."},["edemapolmonare","albumina","ards"]],
["albumina","Albumina","Parametro",["albumina","ipoalbuminemia","pressione oncotica"],{d:"La proteina più abbondante del plasma, prodotta dal fegato.",val:"3,5-5 g/dL.",ap:"Crea la pressione oncotica che trattiene il liquido nei vasi e trasporta farmaci e ormoni. Bassa in malnutrizione, cirrosi, sindrome nefrosica, infiammazione: favorisce edemi diffusi."},["starling"]],
["pressioneidrostatica","Pressione idrostatica","Fisiologia",["pressione idrostatica"],{d:"Pressione esercitata dal sangue sulle pareti dei capillari, che tende a spingere il liquido verso i tessuti.",ap:"Nei capillari polmonari aumenta quando il cuore sinistro non svuota bene: è il meccanismo dell'edema polmonare cardiogeno."},["starling","edemapolmonare"]],

/* ---------- PRIMO SOCCORSO ---------- */
["rcp","Rianimazione cardiopolmonare (RCP)","Procedura",["rianimazione cardiopolmonare","rianimazione","!RCP","compressioni toraciche"],{d:"Sequenza di compressioni toraciche e insufflazioni che mantiene un minimo di circolo e ossigenazione durante un arresto cardiaco.",ap:"Nell'adulto: 30 compressioni e 2 insufflazioni, al centro del torace (metà inferiore dello sterno), profondità 5-6 cm, frequenza 100-120 al minuto, rilasciamento completo, pause ridotte al minimo. Chi non è addestrato o non vuole fare le insufflazioni esegue solo le compressioni."},["arresto","dae","agonico"]],
["arresto","Arresto cardiaco","Clinica",["arresto cardiaco","arresto"],{d:"Il cuore smette di pompare sangue in modo efficace: la persona perde coscienza in pochi secondi e non respira normalmente.",ap:"Ritmi: fibrillazione e tachicardia ventricolare senza polso (defibrillabili), asistolia e attività elettrica senza polso (non defibrillabili). Ogni minuto senza RCP né defibrillazione riduce la sopravvivenza di circa il 10%."},["rcp","dae","fibrillazioneventricolare","asistolia"]],
["agonico","Respiro agonico (gasping)","Segno",["respiro agonico","agonico","gasping"],{d:"Respiri lenti, profondi e rumorosi, irregolari, che compaiono nei primi minuti di un arresto cardiaco.",ap:"Non sono un respiro normale e non portano ossigeno sufficiente. Chi non risponde e respira così va considerato in arresto: si inizia subito la rianimazione."},["arresto","rcp"]],
["dae","DAE (defibrillatore automatico esterno)","Dispositivo",["!DAE","defibrillatore","piastre"],{d:"Apparecchio che analizza il ritmo del cuore tramite due piastre adesive e, se trova un ritmo defibrillabile, eroga una scarica elettrica.",ap:"Si accende e si seguono le istruzioni vocali. Piastre: una sotto la clavicola destra, una sul fianco sinistro all'altezza dell'ascella. Nessuno tocca il paziente durante analisi e scarica. Può essere usato da chiunque, anche senza formazione specifica."},["arresto","fibrillazioneventricolare","rcp"]],
["rosc","Ritorno del circolo spontaneo (ROSC)","Clinica",["ritorno del circolo","!ROSC"],{d:"Ripresa di un'attività cardiaca efficace dopo un arresto: compaiono respiro normale, movimenti, polso.",ap:"Il cuore è instabile e può fermarsi di nuovo: si sorveglia il respiro, si lascia il DAE collegato e si attende il soccorso avanzato."},["arresto","dae"]],
["laccio","Laccio emostatico (tourniquet)","Dispositivo",["laccio emostatico","laccio","tourniquet"],{d:"Fascia che si stringe attorno a un arto per bloccare il flusso di sangue a valle di un'emorragia grave.",ap:"Si applica 5-7 cm sopra la ferita, mai su un'articolazione, e si stringe finché il sangue smette di uscire. Si annota l'ora. Non si allenta fuori dall'ospedale. I lacci commerciali con barretta sono più efficaci di quelli improvvisati."},["emorragiacatastrofica","femorale"]],
["emorragiacatastrofica","Emorragia catastrofica e cABCDE","Clinica",["emorragia catastrofica","emorragia massiva","!cABCDE"],{d:"Sanguinamento esterno così rapido da poter uccidere in pochi minuti, ad esempio da un'arteria di un arto.",ap:"Nel trauma la valutazione diventa cABCDE: prima si controlla l'emorragia catastrofica con compressione diretta, laccio o medicazione emostatica, poi si passa alle vie aeree."},["laccio","shockemorragico"]],
["compressionediretta","Compressione diretta","Procedura",["compressione diretta"],{d:"Pressione forte e continua sulla ferita con la mano, di solito sopra un tessuto pulito ripiegato.",ap:"È il primo gesto per quasi tutte le emorragie esterne. Non si solleva per controllare: si aggiunge altro tessuto sopra se si inzuppa."},["laccio"]],
["shockemorragico","Shock emorragico","Clinica",["shock emorragico"],{d:"Shock dovuto alla perdita di sangue: il volume rimasto non basta a portare ossigeno agli organi.",ap:"Segni: pallore, cute fredda e sudata, polso rapido e debole, sete, confusione, poi calo della pressione. Primo soccorso: fermare l'emorragia, distendere, tenere al caldo, niente da bere."},["shock","triadeletale"]],
["triadeletale","Triade letale del trauma","Fisiologia",["triade letale","coagulopatia"],{d:"Ipotermia, acidosi e coagulopatia: tre condizioni che nel trauma grave si alimentano a vicenda.",ap:"Il freddo rallenta gli enzimi della coagulazione, il sangue coagula peggio e si perde altro sangue. Per questo il ferito va coperto subito."},["ipotermia","shockemorragico"]],
["ipotermia","Ipotermia","Clinica",["ipotermia"],{d:"Temperatura corporea centrale sotto i 35°C.",ap:"Nel trauma peggiora la coagulazione. Si previene coprendo il ferito, anche da sotto, e riducendo l'esposizione."},["triadeletale"]],
["oggettoconficcato","Oggetto conficcato","Clinica",["oggetto conficcato","conficcato"],{d:"Corpo estraneo (coltello, vetro, ferro) rimasto infisso in una ferita.",ap:"Non si estrae fuori dall'ospedale: può tamponare i vasi lesionati. Si blocca con materiale ai lati e si comprime attorno."},["compressionediretta"]],
["ptxiperteso","Pneumotorace iperteso","Clinica",["pneumotorace iperteso"],{d:"Accumulo progressivo di aria nella cavità pleurica sotto pressione, che schiaccia polmone, cuore e grandi vasi.",ap:"Segni: dispnea grave, ipotensione, giugulari turgide, murmure assente da un lato. È un'emergenza che richiede decompressione. Una ferita toracica sigillata male può causarlo."},["pneumotorace","feritatoracica"]],
["feritatoracica","Ferita toracica aperta","Clinica",["ferita toracica aperta","ferita del torace"],{d:"Ferita che mette in comunicazione la cavità toracica con l'esterno; può fare un rumore di risucchio respirando.",ap:"Le linee guida europee di primo soccorso del 2021 consigliano di lasciarla aperta o coprirla con una medicazione non occlusiva, comprimendo solo se sanguina."},["ptxiperteso","pneumotorace"]],
["femorale","Arteria femorale","Anatomia",["arteria femorale"],{d:"Continuazione dell'arteria iliaca esterna sotto il legamento inguinale: porta sangue a tutto l'arto inferiore.",ap:"Superficiale nel triangolo femorale, poi più profonda lungo la coscia; dietro il ginocchio diventa arteria poplitea. Una sua lesione può essere mortale in pochi minuti."},["laccio","venegambe"]],
["colpiscapole","Colpi interscapolari","Procedura",["colpi tra le scapole","colpi interscapolari"],{d:"Colpi decisi con il palmo della mano tra le scapole, con la persona piegata in avanti, per espellere un corpo estraneo dalle vie aeree.",ap:"Nell'adulto cosciente con ostruzione grave: fino a 5 colpi, poi fino a 5 compressioni addominali, alternando. Se perde coscienza: RCP."},["heimlich","ostruzione"]],
["heimlich","Compressioni addominali (manovra di Heimlich)","Procedura",["compressioni addominali","manovra di heimlich","heimlich"],{d:"Spinte rapide verso l'interno e verso l'alto con il pugno sotto lo sterno, abbracciando la persona da dietro.",ap:"Aumentano di colpo la pressione nel torace e spingono fuori il corpo estraneo. Possono causare lesioni interne: dopo l'uso serve sempre una valutazione medica. Non si usano nei lattanti."},["colpiscapole","ostruzione"]],
["ostruzione","Ostruzione delle vie aeree da corpo estraneo","Clinica",["ostruzione","ostruzione completa","andato di traverso"],{d:"Un corpo estraneo, spesso cibo, blocca le vie aeree.",ap:"Lieve: la persona tossisce, parla, respira, e va incoraggiata a tossire. Grave: non riesce a parlare né a tossire efficacemente, labbra blu: colpi tra le scapole e compressioni addominali."},["colpiscapole","heimlich"]],
["crisiepilettica","Crisi epilettica tonico-clonica","Clinica",["crisi epilettica","crisi tonico-clonica","convulsioni","convulsive"],{d:"Scarica elettrica anomala e diffusa dei neuroni: rigidità di tutti i muscoli (fase tonica), poi scosse ritmiche (fase clonica), con perdita di coscienza.",ap:"Non si trattiene la persona e non si mette nulla in bocca. Si protegge la testa, si allontanano gli oggetti, si misura la durata. Dopo: posizione laterale di sicurezza."},["statoepilettico","postcritica"]],
["statoepilettico","Stato epilettico","Clinica",["stato epilettico"],{d:"Crisi che dura più di 5 minuti, o crisi ripetute senza ripresa della coscienza tra una e l'altra.",ap:"È un'emergenza: serve un farmaco (di solito una benzodiazepina) e il 112."},["crisiepilettica"]],
["postcritica","Fase post-critica","Clinica",["post-critica"],{d:"Periodo dopo una crisi epilettica con coscienza ridotta, confusione, sonnolenza e stanchezza.",ap:"Può durare da minuti a ore. La persona va messa sul fianco e sorvegliata."},["crisiepilettica","pls"]],
["colpodicalore","Colpo di calore","Clinica",["colpo di calore","esaurimento da calore"],{d:"Temperatura corporea centrale sopra i 40°C con alterazione del sistema nervoso (confusione, convulsioni, coma).",ap:"Da sforzo (sport, ballo, lavoro al caldo) o classico (anziani in ondate di calore). Si raffredda subito, meglio con immersione in acqua fredda. Il paracetamolo non serve. L'esaurimento da calore è più lieve: temperatura sotto i 40°C e mente lucida."},["ipertermia"]],
["ipertermia","Ipertermia","Clinica",["ipertermia"],{d:"Aumento della temperatura corporea per incapacità di disperdere il calore, con il termostato dell'ipotalamo normale.",ap:"Si distingue dalla febbre, in cui il termostato è alzato: per questo gli antipiretici non funzionano."},["colpodicalore","febbre"]],
["fulmine","Folgorazione da fulmine","Clinica",["fulmine","fulmini","folgorazione"],{d:"Lesione causata da una scarica atmosferica.",ap:"Può causare arresto cardiaco e respiratorio, ustioni, lesioni neurologiche e uditive. La persona colpita non resta carica: si può toccare subito. Con più feriti si usa il triage inverso."},["triageinverso","lichtenberg"]],
["triageinverso","Triage inverso","Procedura",["triage inverso"],{d:"Nei fulmini si dà la priorità a chi sembra morto (in arresto), al contrario dei grandi incidenti.",ap:"Chi è sveglio di solito sopravvive; chi è in arresto spesso si salva solo con una rianimazione immediata, perché il cuore tende a ripartire ma il respiro no."},["fulmine","rcp"]],
["lichtenberg","Figure di Lichtenberg","Segno",["figure di lichtenberg","lichtenberg","a forma di felce"],{d:"Disegni rossastri ramificati sulla pelle dopo un fulmine, dovuti a capillari dilatati lungo il percorso della scarica.",ap:"Non sono ustioni profonde e scompaiono in ore o giorni."},["fulmine"]],
["monossido","Monossido di carbonio","Clinica",["monossido di carbonio","monossido","carbossiemoglobina"],{d:"Gas incolore e inodore prodotto da combustioni con poco ossigeno (stufe, caldaie, bracieri, motori in ambienti chiusi).",ap:"Si lega all'emoglobina circa 200-250 volte più dell'ossigeno formando carbossiemoglobina. Sintomi: mal di testa, nausea, vomito, confusione, sonnolenza, spesso in più persone della stessa casa. Il saturimetro comune dà valori falsamente normali. Terapia: uscire all'aria, ossigeno al 100%, camera iperbarica nei casi gravi."},["iperbarica","saturazione"]],
["iperbarica","Camera iperbarica","Procedura",["camera iperbarica","iperbarica"],{d:"Ambiente in cui si respira ossigeno a una pressione superiore a quella atmosferica.",ap:"Accelera l'eliminazione del monossido e aumenta l'ossigeno sciolto nel plasma. Si usa anche per embolia gassosa e malattia da decompressione."},["monossido"]],
["nue112","Numero unico di emergenza 112","Organizzazione",["!112","!118"],{d:"Il 112 è il numero unico europeo di emergenza: una centrale risponde e smista la chiamata a soccorso sanitario (118), forze dell'ordine o vigili del fuoco.",ap:"Va detto: dove sei, cosa è successo, quante persone sono coinvolte, se respirano e sono coscienti. In vivavoce l'operatore può guidarti nella rianimazione."},[]],
["omissione","Omissione di soccorso","Normativa",["omissione di soccorso"],{d:"Reato previsto dall'articolo 593 del codice penale italiano.",ap:"Chi trova una persona ferita o in pericolo e non presta l'assistenza occorrente, o non avvisa subito le autorità, commette omissione di soccorso. Avvisare il 112 è già una forma di soccorso."},["nue112"]],
["sicurezzascena","Sicurezza della scena","Procedura",["sicurezza della scena","scappa, nasconditi, avvisa"],{d:"Valutazione dei pericoli prima di avvicinarsi a un ferito: traffico, fuoco, gas, elettricità, aggressori, aghi.",ap:"L'ordine dei soccorsi è sicurezza, allarme, soccorso. In un attacco armato vale la regola scappa, nasconditi, avvisa: i sanitari entrano quando la zona è dichiarata sicura."},["nue112"]],
/* ---------- RESPIRO ---------- */
["bpco","BPCO","Clinica",["!BPCO"],{d:"Broncopneumopatia cronica ostruttiva: malattia polmonare cronica con ostruzione al flusso d'aria non completamente reversibile, causata soprattutto dal fumo.",ap:"Comprende bronchite cronica ed enfisema. Riacutizzazioni: aumento di dispnea, tosse ed espettorato, spesso da infezioni. Nei casi gravi c'è ipercapnia cronica: l'obiettivo di saturazione diventa 88-92%."},["ipercapnia","venturi","niv","emogasanalisi"]],
["asma","Asma","Clinica",["asma","asmatic[oa]"],{d:"Malattia infiammatoria cronica delle vie aeree con episodi di broncospasmo reversibile.",ap:"Sintomi: dispnea, sibili, tosse, senso di costrizione toracica. Gli asmatici hanno un rischio maggiore di anafilassi grave."},["broncospasmo","salbutamolo","sibili"]],
["broncospasmo","Broncospasmo","Clinica",["broncospasmo","broncocostrizione"],{d:"Contrazione della muscolatura liscia dei bronchi, con restringimento delle vie aeree.",ap:"Si sentono sibili e l'espirazione è prolungata. Si tratta con β2-agonisti (salbutamolo), nell'anafilassi con adrenalina."},["sibili","salbutamolo","recettorib2"]],
["ipercapnia","Ipercapnia","Clinica",["ipercapni[ac]"],{d:"Anidride carbonica (CO₂) nel sangue arterioso troppo alta: PaCO₂ > 45 mmHg.",ap:"Acuta: acidosi respiratoria, con sonnolenza, cefalea, cute calda, polso pieno, flapping tremor, fino al coma (narcosi carbonica). Cronica (BPCO grave): il rene trattiene bicarbonato e il pH resta quasi normale. La saturazione non la rileva: serve l'emogasanalisi."},["paco2","narcosi","flapping","emogasanalisi"]],
["ipossiemia","Ipossiemia","Clinica",["ipossiemi[ac]","ipossi[ac]","ipossic[oa]"],{d:"Ossigeno nel sangue arterioso troppo basso: PaO₂ < 60 mmHg corrisponde circa a una SpO₂ < 90%.",ap:"Ipossia indica invece l'ossigeno insufficiente nei tessuti. Cause di ipossiemia: alterato rapporto V/Q, shunt, ipoventilazione, ridotta diffusione, bassa FiO₂."},["pao2","saturazione","vq"]],
["cianosi","Cianosi","Segno",["cianosi","cianotic[ho]"],{d:"Colorazione bluastra di cute e mucose, dovuta a un'elevata quantità di emoglobina non legata all'ossigeno.",ap:"Centrale (labbra, lingua): ipossiemia. Periferica (dita): ridotta perfusione o freddo. Può mancare nell'anemia grave e comparire tardi."},["ipossiemia"]],
["flapping","Flapping tremor (asterissi)","Segno",["flapping tremor","flapping"],{d:"Movimento a scatti delle mani tenute estese con i polsi dorsiflessi, come un battito d'ali, dovuto a brevi perdite del tono muscolare.",ap:"Si vede nell'ipercapnia, nell'encefalopatia epatica e nell'uremia."},["ipercapnia"]],
["narcosi","Narcosi carbonica","Clinica",["narcosi"],{d:"Depressione della coscienza fino al coma causata da una CO₂ molto alta.",ap:"Può portare ad arresto respiratorio. Nella BPCO è spesso favorita da ossigeno ad alto flusso o sedativi."},["ipercapnia"]],
["niv","Ventilazione non invasiva (NIV)","Procedura",["ventilazione non invasiva","!NIV"],{d:"Supporto alla respirazione con una maschera (nasale, oronasale, facciale o casco) senza intubazione.",ap:"Nella riacutizzazione di BPCO con acidosi respiratoria (pH < 7,35 e PaCO₂ alta) riduce il ricorso all'intubazione e la mortalità. Compiti infermieristici: scelta e posizionamento della maschera, prevenzione delle lesioni da pressione sul naso, controllo delle perdite, monitoraggio di parametri ed EGA."},["bpco","ipercapnia","cpap"]],
["cpap","CPAP","Dispositivo",["!CPAP"],{d:"Pressione positiva continua nelle vie aeree: un apparecchio mantiene una pressione costante durante tutto il ciclo respiratorio, tenendo aperte le vie aeree.",ap:"A domicilio è la terapia delle apnee ostruttive del sonno. In ospedale si usa anche nell'edema polmonare acuto."},["osas","niv"]],
["osas","Apnee ostruttive del sonno (OSAS)","Clinica",["apnee ostruttive del sonno","apnee notturne","!OSAS"],{d:"Sindrome in cui le vie aeree superiori si chiudono ripetutamente durante il sonno, con pause respiratorie, russamento e cali di saturazione.",ap:"Fattore di rischio importante per la depressione respiratoria da oppioidi e sedativi. Il paziente dovrebbe usare la sua CPAP anche in ospedale."},["cpap","oppioidi"]],
["emogasanalisi","Emogasanalisi (EGA)","Esame",["emogasanalisi","!EGA"],{d:"Esame su sangue arterioso (di solito dall'arteria radiale) che misura pH, PaO₂, PaCO₂, bicarbonato, lattati ed elettroliti.",ap:"Valuta ossigenazione, ventilazione ed equilibrio acido-base. Prima del prelievo radiale si esegue il test di Allen; dopo si comprime a lungo il sito. Va annotata la FiO₂ al momento del prelievo."},["ph","pao2","paco2","bicarbonato","lattati"]],
["ph","pH del sangue","Parametro",["!pH"],{d:"Misura dell'acidità del sangue.",val:"Arterioso 7,35-7,45.",ap:"Sotto 7,35: acidemia (acidosi). Sopra 7,45: alcalemia. Si legge insieme a PaCO₂ (componente respiratoria) e bicarbonato (componente metabolica)."},["acidosi","bicarbonato","paco2"]],
["acidosi","Acidosi","Clinica",["acidosi"],{d:"Processo che tende ad abbassare il pH del sangue.",ap:"Respiratoria: CO₂ trattenuta (ipoventilazione, BPCO, oppioidi). Metabolica: accumulo di acidi o perdita di bicarbonato (chetoacidosi, acidosi lattica, insufficienza renale, diarrea). Spinge il potassio fuori dalle cellule."},["ph","chetoacidosi","kussmaul","potassio"]],
["pao2","PaO₂","Parametro",["pao₂","pao2"],{d:"Pressione parziale dell'ossigeno nel sangue arterioso.",val:"Circa 80-100 mmHg in aria nell'adulto giovane; si riduce con l'età.",ap:"Sotto 60 mmHg si parla di insufficienza respiratoria."},["emogasanalisi","ipossiemia"]],
["paco2","PaCO₂","Parametro",["paco₂","paco2"],{d:"Pressione parziale dell'anidride carbonica nel sangue arterioso: riflette la ventilazione.",val:"35-45 mmHg.",ap:"Alta: ipoventilazione (ipercapnia). Bassa: iperventilazione (ansia, compenso di un'acidosi metabolica come nel Kussmaul)."},["ipercapnia","emogasanalisi"]],
["saturazione","Saturazione (SpO₂)","Parametro",["spo₂","spo2","saturazion[ei]","saturimetro"],{d:"Percentuale di emoglobina legata all'ossigeno, misurata con il saturimetro (pulsossimetro) sul dito o sul lobo dell'orecchio.",val:"Di solito 94-98%; nei pazienti a rischio di ipercapnia obiettivo 88-92%.",ap:"Non misura la CO₂. Può essere falsata da mani fredde, smalto, movimento, cattiva perfusione, monossido di carbonio (sovrastima), cute molto pigmentata (possibile sovrastima)."},["ossigeno","ipossiemia","ipercapnia"]],
["fio2","FiO₂","Parametro",["fio₂","fio2"],{d:"Frazione di ossigeno nell'aria inspirata.",val:"Aria ambiente 21%.",ap:"Valori indicativi: occhialini a 1-4 L/min circa 24-36%, maschera semplice 35-50%, Venturi fissa al valore scelto (24-60%), reservoir fino a circa 60-90%."},["ossigeno","venturi"]],
["venturi","Maschera Venturi","Dispositivo",["maschera venturi","venturi"],{d:"Maschera con un ugello colorato che mescola ossigeno e aria ambiente in proporzione fissa.",ap:"Fornisce una FiO₂ precisa (24%, 28%, 31%, 35%, 40%, 60%) indipendentemente dal respiro del paziente, se si imposta il flusso indicato sull'ugello. Indicata quando serve titolare, come nella BPCO ipercapnica."},["fio2","bpco","ossigeno"]],
["occhialini","Occhialini nasali","Dispositivo",["occhialini nasali","occhialini"],{d:"Cannula a due punte inserita nelle narici, per somministrare ossigeno a basso flusso (1-4 L/min).",ap:"Comodi: permettono di parlare e mangiare. La FiO₂ reale varia con il respiro e con la bocca aperta. Sopra 4 L/min seccano le mucose."},["fio2","ossigeno"]],
["mascherasemplice","Maschera semplice","Dispositivo",["maschera semplice"],{d:"Maschera facciale senza valvole né reservoir, per ossigeno a 5-10 L/min.",ap:"Sotto 5 L/min non elimina bene la CO₂ espirata dalla maschera."},["fio2"]],
["reservoir","Maschera con reservoir","Dispositivo",["reservoir"],{d:"Maschera con un sacchetto che si riempie di ossigeno puro e valvole che limitano l'aria esterna, a 10-15 L/min.",ap:"Fornisce le concentrazioni più alte senza ventilazione. Indicata nelle ipossiemie critiche (trauma, shock, arresto); pericolosa nei pazienti ipercapnici se lasciata a lungo."},["fio2","ipercapnia"]],
["vq","Rapporto ventilazione/perfusione","Fisiologia",["ventilazione\\/perfusione","v\\/q"],{d:"Rapporto tra l'aria che arriva agli alveoli (ventilazione, V) e il sangue che passa nei capillari polmonari (perfusione, Q).",val:"In media circa 0,8 nel polmone sano.",ap:"V/Q basso: alveoli perfusi ma poco ventilati (polmonite, edema, atelettasia, BPCO). V/Q alto o spazio morto: alveoli ventilati ma poco perfusi (embolia polmonare). Lo squilibrio V/Q è la causa più comune di ipossiemia."},["spaziomorto","embolia","vasocostrizioneipossica"]],
["spaziomorto","Spazio morto","Fisiologia",["spazio morto"],{d:"Parte dell'aria inspirata che non partecipa allo scambio dei gas.",ap:"Anatomico: vie aeree di conduzione (circa 150 mL). Alveolare: alveoli ventilati ma non perfusi, come nell'embolia polmonare."},["vq"]],
["haldane","Effetto Haldane","Fisiologia",["effetto haldane","haldane"],{d:"L'emoglobina legata all'ossigeno trasporta meno CO₂ di quella deossigenata.",ap:"Quando si dà molto ossigeno, l'emoglobina rilascia CO₂ nel sangue: in un paziente che non può aumentare la ventilazione la PaCO₂ sale."},["ipercapnia","vq"]],
["chemocettori","Chemocettori","Fisiologia",["chemocettor[ie]"],{d:"Recettori che rilevano la composizione chimica del sangue e regolano il respiro.",ap:"Centrali (superficie ventrale del bulbo): sensibili a CO₂ e pH del liquor, guidano la maggior parte della ventilazione a riposo. Periferici (glomi carotidei e aortici): sensibili soprattutto al calo di O₂, e anche a CO₂ e pH."},["bulbo","glomi"]],
["glomi","Glomi carotidei e aortici","Anatomia",["glom[io] carotide[io]","glom[io] aortic[io]","glomi"],{d:"Piccole strutture alla biforcazione della carotide comune (carotidei) e sull'arco aortico (aortici), con chemocettori periferici.",ap:"I carotidei inviano segnali tramite il nervo glossofaringeo, gli aortici tramite il vago."},["chemocettori"]],
["bulbo","Bulbo (midollo allungato)","Anatomia",["bulbo","midollo allungato"],{d:"Parte più bassa del tronco encefalico, tra ponte e midollo spinale.",ap:"Contiene i centri del respiro (tra cui il complesso pre-Bötzinger), del controllo cardiovascolare, della deglutizione, della tosse e del vomito. Qui avviene la decussazione delle piramidi."},["ponte","prebotzinger","decussazione","chemocettori"]],
["ponte","Ponte","Anatomia",["ponte"],{d:"Parte del tronco encefalico tra mesencefalo e bulbo.",ap:"Contiene centri che modulano il ritmo respiratorio (pneumotassico e apneustico) e i nuclei di diversi nervi cranici."},["bulbo"]],
["prebotzinger","Complesso pre-Bötzinger","Anatomia",["pre-bötzinger"],{d:"Gruppo di neuroni del bulbo ventrale che genera il ritmo automatico dell'inspirazione.",ap:"È ricco di recettori μ: per questo gli oppioidi rallentano il respiro."},["bulbo","recettorimu"]],
["frenico","Nervo frenico","Anatomia",["frenic[io]","c3-c5"],{d:"Nervo che comanda il diaframma, originato dalle radici cervicali C3-C5.",ap:"Una lesione del midollo sopra C3 abolisce la respirazione spontanea."},["diaframma"]],
["diaframma","Diaframma","Anatomia",["diaframma"],{d:"Muscolo a cupola che separa torace e addome: è il principale muscolo inspiratorio.",ap:"Contraendosi si abbassa e allarga il torace. Da sdraiati i visceri lo spingono in alto e lavora peggio: per questo il paziente dispnoico sta meglio seduto."},["frenico","ortopnea"]],
["pneumotorace","Pneumotorace","Clinica",["pneumotorace"],{d:"Presenza di aria nello spazio pleurico, con collasso parziale o totale del polmone.",ap:"Segni: dolore improvviso, dispnea, murmure ridotto o assente e iperfonesi dal lato colpito. Iperteso: spostamento del mediastino, ipotensione, è un'emergenza."},["ipotensione"]],
["addensamento","Addensamento polmonare","Segno",["addensamento","polmonit[ei]"],{d:"Zona di polmone in cui l'aria degli alveoli è sostituita da essudato, come nella polmonite.",ap:"All'esame: ottusità alla percussione, aumento del fremito vocale tattile, soffio bronchiale, crepitii localizzati. La polmonite ab ingestis nasce dall'aspirazione di cibo, liquidi o saliva."},["fremito","disfagia"]],
["fremito","Fremito vocale tattile","Segno",["fremito vocale tattile","fremito"],{d:"Vibrazione percepita con la mano sul torace mentre il paziente pronuncia ad esempio \"trentatré\".",ap:"Aumenta negli addensamenti, si riduce in versamento pleurico, pneumotorace ed enfisema."},["addensamento"]],
["ards","ARDS","Clinica",["!ARDS"],{d:"Sindrome da distress respiratorio acuto: danno diffuso della membrana alveolo-capillare con edema polmonare non cardiogeno e ipossiemia grave.",ap:"Cause: sepsi, polmonite, aspirazione, trauma, pancreatite, trasfusioni massive."},["edemapolmonare","sepsi"]],
["kussmaul","Respiro di Kussmaul","Segno",["kussmaul"],{d:"Respiro profondo, rapido e regolare, a volte faticoso.",ap:"È il compenso di un'acidosi metabolica: eliminando più CO₂ il pH risale un po'. Tipico della chetoacidosi diabetica e dell'acidosi in insufficienza renale."},["chetoacidosi","acidosi","paco2"]],
["cheynestokes","Respiro di Cheyne-Stokes","Segno",["cheyne-stokes"],{d:"Respiro con atti che aumentano e poi diminuiscono di profondità, alternati a pause di apnea.",ap:"Si osserva nello scompenso cardiaco grave, in alcune lesioni cerebrali, in alta quota e nel fine vita."},[]],
["tachipnea","Tachipnea","Parametro",["tachipnea"],{d:"Frequenza respiratoria aumentata, oltre 20 atti al minuto nell'adulto.",ap:"È uno dei segni più precoci e sensibili di deterioramento: compare in sepsi, ipossiemia, acidosi, dolore, ansia."},["news2"]],
["depressionerespiratoria","Depressione respiratoria","Clinica",["depressione respiratoria","ipoventila[rz][a-z]*"],{d:"Riduzione della ventilazione per azione sui centri respiratori o sui muscoli: respiro lento o superficiale, CO₂ che sale.",ap:"Da oppioidi, benzodiazepine, anestetici, lesioni del tronco encefalico. Con gli oppioidi è di solito preceduta dalla sedazione."},["oppioidi","naloxone","sedazione"]],
["dolorepleuritico","Dolore pleuritico","Segno",["pleuritic[oa]","dolore toracico che peggiora inspirando"],{d:"Dolore toracico trafittivo che aumenta con l'inspirazione profonda e la tosse, dovuto a irritazione della pleura.",ap:"Cause: pleurite, polmonite, embolia polmonare, pneumotorace, pericardite."},["embolia","pneumotorace"]],
["emottisi","Emottisi","Segno",["emottisi"],{d:"Emissione di sangue con la tosse, proveniente dalle vie respiratorie.",ap:"Cause: infezioni, bronchiectasie, tumori, embolia polmonare, edema polmonare (espettorato rosato)."},[]],

/* ---------- ALLERGIA E IMMUNOLOGIA ---------- */
["anafilassi","Anafilassi","Clinica",["anafilassi","anafilattic[oa]"],{d:"Reazione allergica generalizzata grave, a rapida insorgenza, che coinvolge vie aeree, respiro o circolo e può essere mortale.",ap:"Cause frequenti: farmaci (antibiotici beta-lattamici, FANS, miorilassanti), punture di insetti, alimenti, lattice. Segni: orticaria, angioedema, broncospasmo, stridore, ipotensione, sintomi gastrointestinali. Trattamento: adrenalina IM subito, posizione, ossigeno, liquidi."},["adrenalina","mastociti","istamina","orticaria","angioedema","bifasica"]],
["orticaria","Orticaria","Segno",["orticaria"],{d:"Pomfi rilevati, arrossati e pruriginosi sulla pelle, che cambiano forma e posizione in poche ore.",ap:"Dovuta al rilascio di istamina nel derma. Da sola è benigna, ma insieme a sintomi respiratori o circolatori indica anafilassi."},["istamina","anafilassi"]],
["angioedema","Angioedema","Segno",["angioedema","labbra e lingua gonfie","labbra gonfie"],{d:"Gonfiore profondo di cute e mucose (labbra, palpebre, lingua, laringe).",ap:"Pericoloso quando coinvolge lingua e laringe: voce rauca e stridore indicano rischio di ostruzione. Può essere allergico (istaminico) o da ACE-inibitori (da bradichinina, non risponde agli antistaminici)."},["anafilassi","acei"]],
["mastociti","Mastociti","Anatomia",["mastocit[ai]"],{d:"Cellule del sistema immunitario presenti nei tessuti, soprattutto vicino a vasi, cute e mucose, ricche di granuli.",ap:"Hanno sulla superficie IgE: quando l'allergene le lega, liberano istamina, triptasi, leucotrieni e altri mediatori."},["istamina","ige","triptasi"]],
["istamina","Istamina","Fisiologia",["istamina"],{d:"Mediatore liberato da mastociti e basofili.",ap:"Sui recettori H1: vasodilatazione, aumento della permeabilità dei capillari, prurito, contrazione dei bronchi. Sui recettori H2: secrezione acida gastrica."},["mastociti","antistaminici"]],
["ige","IgE","Fisiologia",["!IgE"],{d:"Classe di anticorpi coinvolta nelle allergie e nella difesa dai parassiti.",ap:"Si legano ai mastociti; al secondo contatto con l'allergene ne provocano la degranulazione."},["mastociti","anafilassi"]],
["triptasi","Triptasi","Esame",["triptasi"],{d:"Enzima liberato dai mastociti.",ap:"Il dosaggio nel sangue (idealmente entro 1-2 ore dall'inizio della reazione e poi a distanza) aiuta a confermare un'anafilassi."},["mastociti"]],
["leucotrieni","Leucotrieni","Fisiologia",["leucotrieni"],{d:"Mediatori lipidici dell'infiammazione prodotti da mastociti e altre cellule.",ap:"Causano broncocostrizione prolungata e aumento della permeabilità vascolare. Il montelukast ne blocca i recettori."},["mastociti"]],
["bifasica","Reazione bifasica","Clinica",["bifasica"],{d:"Ritorno dei sintomi di anafilassi dopo la risoluzione iniziale, senza nuova esposizione, di solito entro 12 ore.",ap:"Per questo dopo un'anafilassi il paziente resta in osservazione per alcune ore e viene dimesso con istruzioni chiare."},["anafilassi"]],
["recettoria1","Recettori α1","Fisiologia",["α1"],{d:"Recettori adrenergici della muscolatura liscia dei vasi.",ap:"Stimolati da adrenalina e noradrenalina, provocano vasocostrizione: aumentano la pressione e riducono l'edema delle mucose."},["adrenalina","vasocostrizione"]],
["recettorib1","Recettori β1","Fisiologia",["β1"],{d:"Recettori adrenergici soprattutto del cuore.",ap:"Stimolati, aumentano frequenza, forza di contrazione e velocità di conduzione. Bloccati dai betabloccanti cardioselettivi come il bisoprololo."},["adrenalina","bisoprololo"]],
["recettorib2","Recettori β2","Fisiologia",["β2"],{d:"Recettori adrenergici di bronchi, vasi dei muscoli, utero.",ap:"Stimolati, rilasciano la muscolatura bronchiale (broncodilatazione) e spostano il potassio nelle cellule. Sono il bersaglio del salbutamolo."},["salbutamolo","adrenalina","broncospasmo"]],
["recettorimu","Recettori μ (mu)","Fisiologia",["recettor[ie] μ"],{d:"Principali recettori degli oppioidi, presenti nel cervello, nel tronco encefalico, nel midollo spinale e nell'intestino.",ap:"La loro attivazione dà analgesia, ma anche depressione respiratoria, sedazione, miosi, stipsi, nausea, prurito."},["oppioidi","morfina","naloxone"]],
["antagonista","Antagonista competitivo","Farmacologia",["antagonista competitivo","antagonista puro","antagonista"],{d:"Farmaco che si lega allo stesso recettore dell'agonista senza attivarlo, impedendo all'agonista di agire.",ap:"L'effetto dipende dalle concentrazioni dei due: una dose maggiore di agonista può superare il blocco, e viceversa."},["naloxone","agonistaparziale"]],
["agonistaparziale","Agonista parziale","Farmacologia",["agonista parziale"],{d:"Farmaco che attiva il recettore solo in parte, anche a recettori tutti occupati.",ap:"Ha un effetto massimo inferiore all'agonista pieno. Se dato a chi assume un agonista pieno può ridurne l'effetto."},["buprenorfina"]],

/* ---------- TRASFUSIONE ---------- */
["trasfusione","Trasfusione","Procedura",["trasfusion[ei]","trasfus[oiae]"],{d:"Somministrazione EV di sangue o emocomponenti (emazie, piastrine, plasma).",ap:"Passaggi di sicurezza: consenso, prelievo per la compatibilità con identificazione corretta, controllo al letto con identificazione attiva e doppio operatore, parametri prima dell'avvio, presenza nei primi 15 minuti, controlli fino alla fine, documentazione."},["emazie","identificazione","reazioneemolitica"]],
["gruppoabo","Gruppi sanguigni ABO","Fisiologia",["gruppo sanguigno","gruppo 0","gruppo a","!ABO"],{d:"Classificazione del sangue in base agli antigeni A e B sui globuli rossi: gruppo A, B, AB, 0.",ap:"Nel plasma ci sono anticorpi naturali contro gli antigeni assenti: chi è 0 ha anti-A e anti-B; chi è AB non ne ha. Emazie compatibili: 0 a tutti (donatore universale di emazie), AB riceve da tutti. Per il plasma vale il contrario."},["rh","anticorpi","reazioneemolitica"]],
["rh","Fattore Rh","Fisiologia",["fattore rh","!Rh"],{d:"Antigene D presente (Rh positivo) o assente (Rh negativo) sui globuli rossi.",ap:"Gli anticorpi anti-D non sono naturali: si formano dopo un contatto (trasfusione, gravidanza). Per questo nelle donne Rh negative in gravidanza si fa la profilassi con immunoglobuline anti-D."},["gruppoabo"]],
["anticorpi","Anticorpi","Fisiologia",["anticorp[oi]","!IgM"],{d:"Proteine prodotte dai linfociti B che riconoscono e legano bersagli specifici (antigeni).",ap:"Classi: IgG, IgM, IgA, IgE, IgD. Gli anti-A e anti-B sono soprattutto IgM, grandi e capaci di attivare con forza il complemento."},["complemento","gruppoabo","ige"]],
["complemento","Complemento","Fisiologia",["complemento"],{d:"Sistema di proteine del sangue che, una volta attivato da anticorpi o microbi, forma pori nelle membrane delle cellule bersaglio e richiama l'infiammazione.",ap:"Nella reazione emolitica ABO perfora i globuli rossi trasfusi nei vasi (emolisi intravascolare)."},["anticorpi","emolisi"]],
["emolisi","Emolisi","Clinica",["emolisi","emolizzat[oa]"],{d:"Rottura dei globuli rossi con liberazione di emoglobina.",ap:"Intravascolare: nei vasi, come nella reazione ABO (emoglobinuria, danno renale). Extravascolare: nella milza. Un campione di sangue emolizzato (da prelievo difficile, laccio prolungato, agitazione) può dare un potassio falsamente alto."},["emoglobinuria","reazioneemolitica","potassio"]],
["emoglobinuria","Emoglobinuria","Segno",["emoglobinuria","urine scure"],{d:"Presenza di emoglobina libera nelle urine, che diventano rosso-brunastre.",ap:"Indica emolisi intravascolare. L'emoglobina è tossica per i tubuli renali: va sorvegliata la diuresi."},["emolisi"]],
["reazioneemolitica","Reazione trasfusionale emolitica acuta","Clinica",["reazione emolitica","reazione trasfusionale"],{d:"Distruzione rapida dei globuli rossi trasfusi da parte degli anticorpi del ricevente, di solito per incompatibilità ABO.",ap:"Compare spesso nei primi minuti: febbre, brividi, dolore lombare o lungo la vena, angoscia, ipotensione, tachicardia, urine scure, sanguinamenti. Si ferma subito la trasfusione, si mantiene l'accesso con fisiologica e deflussore nuovo, si chiama il medico, si ricontrollano identità e sacca, si inviano sacca e campioni."},["trasfusione","gruppoabo","cid","emovigilanza"]],
["reazionefebbrile","Reazione febbrile non emolitica","Clinica",["reazione febbrile non emolitica"],{d:"Febbre e brividi durante o dopo una trasfusione, senza emolisi, dovuti a citochine o ad anticorpi contro i leucociti del donatore.",ap:"È la reazione più frequente e di solito benigna, ma all'inizio non si distingue con certezza da una emolitica: si ferma comunque la trasfusione e si avvisa il medico."},["reazioneemolitica"]],
["cid","Coagulazione intravascolare disseminata (CID)","Clinica",["coagulazione intravascolare"],{d:"Attivazione diffusa della coagulazione nei piccoli vasi, che consuma piastrine e fattori.",ap:"Paradossalmente causa sia microtrombi negli organi sia sanguinamenti. Si associa a sepsi, traumi, complicanze ostetriche, reazioni trasfusionali gravi."},["sepsi","reazioneemolitica"]],
["emovigilanza","Emovigilanza","Organizzazione",["emovigilanza"],{d:"Sistema di segnalazione e analisi degli eventi avversi legati alla trasfusione, dal donatore al ricevente.",ap:"Ogni reazione o quasi-errore va segnalato al servizio trasfusionale: serve a correggere i processi."},["trasfusione"]],
["identificazione","Identificazione attiva","Procedura",["identificazione attiva","identificazione passiva","identificazione"],{d:"Verifica dell'identità in cui il paziente dichiara lui stesso nome, cognome e data di nascita, confrontati con braccialetto e documenti.",ap:"L'identificazione passiva (\"Lei è il signor...?\") è insicura: il paziente può rispondere sì per confusione, ansia o sordità. Nei pazienti non collaboranti si usa il braccialetto con un secondo operatore."},["trasfusione"]],
["irradiazione","Emocomponenti irradiati","Procedura",["irradiat[ao]","irradiazione"],{d:"Emocomponenti trattati con radiazioni per inattivare i linfociti del donatore.",ap:"Prevengono la malattia del trapianto contro l'ospite associata a trasfusione in pazienti immunodepressi (es. trapiantati, alcuni pazienti oncoematologici)."},[]],

/* ---------- NEUROLOGIA ---------- */
["ictus","Ictus","Clinica",["ictus"],{d:"Deficit neurologico improvviso dovuto a un problema dei vasi cerebrali.",ap:"Ischemico (circa 80-85%): un vaso si chiude per trombo o embolo. Emorragico: un vaso si rompe. Si riconosce con FAST/BE-FAST. Il tempo è decisivo: TC urgente, eventuale trombolisi o trombectomia."},["ischemia","penombra","fast","alteplase","tc"]],
["ischemia","Ischemia","Clinica",["ischemi[ac]","ischemico"],{d:"Riduzione o arresto dell'afflusso di sangue a un tessuto, con carenza di ossigeno e nutrienti.",ap:"Se prolungata porta a infarto, cioè morte del tessuto. I neuroni sono tra le cellule più sensibili: senza flusso smettono di funzionare in secondi e muoiono in minuti."},["ictus","penombra","core"]],
["penombra","Penombra ischemica","Fisiologia",["penombra"],{d:"Zona di tessuto cerebrale attorno al core dell'ictus, che riceve poco sangue e non funziona, ma è ancora vivo e salvabile.",ap:"È il bersaglio di trombolisi e trombectomia. Se il flusso non torna, nel tempo diventa infarto. Abbassare troppo la pressione riduce il flusso alla penombra."},["core","ischemia","alteplase"]],
["core","Core ischemico","Fisiologia",["core"],{d:"Zona centrale dell'ictus con flusso quasi assente, già andata incontro a morte cellulare.",ap:"Non è recuperabile; la terapia cerca di impedire che si allarghi alla penombra."},["penombra"]],
["trombo","Trombo","Clinica",["tromb[oi]"],{d:"Coagulo di sangue che si forma all'interno di un vaso o del cuore e vi rimane attaccato.",ap:"Si forma per stasi, danno della parete o ipercoagulabilità (triade di Virchow)."},["embolo","virchow","tvp"]],
["embolo","Embolo","Clinica",["embol[oi]"],{d:"Materiale che viaggia nel sangue e si ferma in un vaso più piccolo, chiudendolo: spesso un frammento di trombo, ma anche aria, grasso o liquido amniotico.",ap:"Dalle vene delle gambe gli emboli vanno al polmone; dal cuore sinistro (es. fibrillazione atriale) al cervello e alle altre arterie."},["trombo","embolia","ictus"]],
["acm","Arteria cerebrale media","Anatomia",["arteria cerebrale media","cerebrale media"],{d:"Ramo principale della carotide interna: irriga la faccia laterale degli emisferi.",ap:"Un'occlusione dà emiparesi e deficit sensitivo controlaterali, prevalenti a volto e braccio, e, se è a sinistra, spesso afasia. È l'arteria più colpita dagli ictus ischemici."},["afasia","emiparesi","ictus","aca"]],
["aca","Arteria cerebrale anteriore","Anatomia",["arteria cerebrale anteriore","cerebrale anteriore"],{d:"Ramo della carotide interna che irriga la faccia mediale dei lobi frontali e parietali.",ap:"Un'occlusione dà deficit prevalente all'arto inferiore controlaterale e disturbi del comportamento."},["acm"]],
["afasia","Afasia","Segno",["afasia"],{d:"Disturbo del linguaggio (produzione o comprensione) dovuto a lesione cerebrale, con apparato fonatorio integro.",ap:"Di Broca: eloquio stentato, comprensione relativamente conservata. Di Wernicke: eloquio fluente ma privo di senso, comprensione compromessa. Va distinta dalla disartria."},["broca","wernicke","disartria"]],
["broca","Area di Broca","Anatomia",["broca"],{d:"Area del lobo frontale inferiore, di solito a sinistra, coinvolta nella produzione del linguaggio."},["afasia","wernicke"]],
["wernicke","Area di Wernicke","Anatomia",["wernicke"],{d:"Area del lobo temporale superiore posteriore, di solito a sinistra, coinvolta nella comprensione del linguaggio."},["afasia","broca"]],
["disartria","Disartria","Segno",["disartria"],{d:"Difficoltà ad articolare le parole per un problema dei muscoli o del loro controllo (cervelletto, tronco, nervi cranici), con linguaggio integro.",ap:"Il paziente sa cosa vuole dire e capisce, ma parla in modo impastato o scandito."},["afasia","cervelletto"]],
["emiparesi","Emiparesi","Segno",["emiparesi","paralisi"],{d:"Riduzione della forza in una metà del corpo; emiplegia se la forza è assente.",ap:"Una lesione di un emisfero dà deficit dal lato opposto per l'incrocio delle vie motorie."},["decussazione","acm"]],
["decussazione","Decussazione delle piramidi","Anatomia",["decussazione"],{d:"Punto nella parte bassa del bulbo in cui circa l'85-90% delle fibre della via corticospinale passa dal lato opposto.",ap:"Spiega perché ogni emisfero comanda la metà opposta del corpo."},["bulbo","emiparesi"]],
["cervelletto","Cervelletto","Anatomia",["cervelletto"],{d:"Struttura sotto i lobi occipitali, dietro al tronco encefalico, che coordina movimento, equilibrio e postura.",ap:"Lesioni: atassia, tremore intenzionale, nistagmo, disartria. I suoi deficit sono dallo stesso lato della lesione."},["disartria"]],
["fast","FAST / BE-FAST","Scala",["be-fast","!FAST"],{d:"Acronimo per riconoscere l'ictus: Face (asimmetria del volto), Arm (debolezza di un braccio), Speech (alterazione del linguaggio), Time (chiamare subito e annotare l'ora).",ap:"BE-FAST aggiunge Balance (perdita di equilibrio) ed Eyes (disturbi visivi improvvisi). In ospedale la gravità si quantifica con la scala NIHSS."},["ictus","lkw"]],
["lkw","Ultimo momento noto in benessere","Procedura",["ultimo momento noto in benessere","ultima volta visto bene","ultima volta","visto in benessere"],{d:"Ultimo orario documentato in cui il paziente è stato visto senza sintomi. In inglese last known well.",ap:"Se l'esordio non è stato osservato (al risveglio, trovato a terra) si usa questo orario per decidere sulla trombolisi, non quello della scoperta dei sintomi."},["alteplase","ictus"]],
["disfagia","Disfagia","Clinica",["disfagia","deglutizione"],{d:"Difficoltà a deglutire cibi, liquidi o saliva.",ap:"Frequente dopo ictus. Rischio di aspirazione e polmonite ab ingestis. Prima di dare qualsiasi cosa per bocca si esegue uno screening della deglutizione da personale formato; poi si adattano consistenze (liquidi addensati, cibi morbidi) e postura."},["addensamento","ictus"]],
["tc","TC (tomografia computerizzata)","Esame",["!TC"],{d:"Esame radiologico che ricostruisce immagini a strati del corpo con raggi X.",ap:"Nell'ictus la TC senza contrasto esclude un'emorragia prima della trombolisi; l'angio-TC cerca l'occlusione dei grandi vasi."},["ictus","alteplase"]],
["gcs","Glasgow Coma Scale","Scala",["!GCS","glasgow"],{d:"Scala dello stato di coscienza da 3 a 15: apertura degli occhi (1-4), risposta verbale (1-5), risposta motoria (1-6).",ap:"GCS ≤ 8 indica coma, con possibile perdita di protezione delle vie aeree."},["sedazione"]],
["sedazione","Sedazione","Clinica",["sedazione","sedat[oa]","sonnolent[oa]"],{d:"Riduzione dello stato di vigilanza, da lieve sonnolenza al coma.",ap:"Con gli oppioidi si valuta con scale dedicate (ad esempio POSS: 1 sveglio, 2 lievemente sonnolento facilmente risvegliabile, 3 frequentemente sonnolento si addormenta parlando, 4 difficilmente risvegliabile). Dal livello 3 si riduce o sospende l'oppioide."},["depressionerespiratoria","oppioidi","gcs"]],
["miosi","Miosi","Segno",["miosi","pupille a capocchia di spillo","pupille puntiformi"],{d:"Pupille ristrette.",ap:"Tipica degli oppioidi; anche da lesioni del ponte, organofosfati, alcuni colliri. La midriasi (pupille dilatate) si vede invece in astinenza da oppioidi, anticolinergici, simpaticomimetici."},["oppioidi","astinenza"]],
["astinenza","Astinenza da oppioidi","Clinica",["astinenza"],{d:"Sindrome che compare quando un oppioide assunto a lungo viene sospeso o antagonizzato.",ap:"Segni: ansia, agitazione, sudorazione, lacrimazione, rinorrea, sbadigli, midriasi, dolori, crampi, diarrea, tachicardia. Raramente pericolosa per la vita nell'adulto, ma molto sgradevole."},["naloxone","miosi"]],
["rinarcotizzazione","Ri-narcotizzazione","Clinica",["ri-narcotizzazione"],{d:"Ritorno della sedazione e della depressione respiratoria quando l'effetto del naloxone finisce prima di quello dell'oppioide.",ap:"È particolarmente probabile con oppioidi a lunga durata o a rilascio prolungato. Impone sorveglianza per ore dopo l'antidoto."},["naloxone"]],
["pca","PCA (analgesia controllata dal paziente)","Dispositivo",["!PCA"],{d:"Pompa che eroga un bolo di analgesico, di solito un oppioide, quando il paziente preme un pulsante, con un intervallo minimo di blocco tra un bolo e l'altro.",ap:"La sicurezza si basa sul fatto che un paziente troppo sedato smette di premere: per questo solo il paziente deve usare il pulsante. Si controllano dolore, sedazione, FR, numero di boli richiesti ed erogati."},["morfina","sedazione"]],

/* ---------- EMBOLIA E TROMBOSI ---------- */
["embolia","Embolia polmonare","Clinica",["embolia polmonare","embolia"],{d:"Ostruzione dell'arteria polmonare o dei suoi rami, di solito da un trombo partito dalle vene profonde delle gambe.",ap:"Segni: dispnea improvvisa, tachicardia, dolore pleuritico, ipossiemia, a volte emottisi, sincope o shock. Diagnosi con angio-TC. Terapia: anticoagulanti; trombolisi nelle forme con shock."},["tvp","vq","wells","anticoagulante"]],
["tvp","Trombosi venosa profonda","Clinica",["trombosi venosa profonda","trombosi venosa","trombosi","!TVP"],{d:"Formazione di un trombo in una vena profonda, quasi sempre degli arti inferiori.",ap:"Segni: gonfiore di un polpaccio o di una gamba, calore, dolore, arrossamento; spesso pochi sintomi. Si conferma con ecocolordoppler. Non si massaggia la gamba."},["embolia","virchow","enoxaparina"]],
["virchow","Triade di Virchow","Fisiologia",["triade di virchow","virchow"],{d:"I tre fattori che favoriscono la trombosi: stasi del sangue, danno della parete del vaso, ipercoagulabilità.",ap:"Esempi: immobilità e allettamento (stasi), chirurgia e traumi (danno), tumori, gravidanza, estrogeni, trombofilie (ipercoagulabilità)."},["tvp","trombo"]],
["wells","Punteggio di Wells","Scala",["wells"],{d:"Punteggio che stima la probabilità clinica di embolia polmonare (o di TVP).",ap:"Per l'embolia considera segni di TVP, diagnosi alternativa meno probabile, FC > 100, immobilizzazione o chirurgia recente, precedente tromboembolia, emottisi, tumore attivo."},["embolia","tvp"]],
["ventricolodx","Ventricolo destro","Anatomia",["ventricolo destro"],{d:"Cavità del cuore che pompa il sangue venoso nell'arteria polmonare.",ap:"Ha pareti sottili ed è adatto a basse pressioni: in un'embolia massiva si dilata e può cedere."},["embolia"]],
["cava","Vena cava","Anatomia",["vena cava","cava inferiore","cava superiore","cava"],{d:"Le due grandi vene che riportano il sangue all'atrio destro: superiore (dalla parte alta del corpo) e inferiore (dalla parte bassa)."},["ventricolodx"]],
["venegambe","Vene femorale, poplitea, iliaca","Anatomia",["femorale","poplitea","iliaca"],{d:"Vene profonde dell'arto inferiore e del bacino: la poplitea dietro il ginocchio continua nella femorale, che diventa iliaca esterna e poi, unita all'interna, iliaca comune, fino alla cava inferiore."},["tvp","cava"]],
["polmonare","Arteria polmonare e vene polmonari","Anatomia",["arteria polmonare","vene polmonari"],{d:"L'arteria polmonare porta sangue povero di ossigeno dal ventricolo destro ai polmoni; le vene polmonari riportano sangue ossigenato all'atrio sinistro.",ap:"Sono gli unici vasi in cui l'arteria trasporta sangue venoso e le vene sangue arterioso."},["embolia"]],
["forameovale","Forame ovale pervio","Anatomia",["forame ovale","embolia paradossa"],{d:"Piccola comunicazione tra i due atri, normale nel feto, che in circa un adulto su quattro non si chiude del tutto.",ap:"Può permettere a un embolo venoso di passare a sinistra e arrivare al cervello (embolia paradossa)."},["embolo","ictus"]],
["calze","Calze a compressione graduata","Dispositivo",["calze elastiche","calze"],{d:"Calze che esercitano una pressione decrescente dalla caviglia alla coscia per favorire il ritorno venoso.",ap:"Vanno misurate e controllate ogni giorno (pelle, circolazione). Controindicate in arteriopatia periferica grave, neuropatia grave, lesioni cutanee della gamba."},["tvp","arteriopatia"]],
["arteriopatia","Arteriopatia periferica","Clinica",["arteriopatia periferica"],{d:"Restringimento delle arterie degli arti, quasi sempre per aterosclerosi.",ap:"Sintomi: dolore al polpaccio camminando (claudicatio), polsi deboli, cute fredda e pallida, ulcere. Le calze compressive possono peggiorare l'ischemia."},["calze"]],

/* ---------- SEPSI E INFEZIONI ---------- */
["sepsi","Sepsi","Clinica",["seps[ie]","settic[oa]"],{d:"Disfunzione d'organo pericolosa per la vita causata da una risposta alterata dell'organismo a un'infezione (definizione Sepsis-3).",ap:"Shock settico: sepsi con bisogno di vasopressori per mantenere PAM ≥ 65 mmHg e lattati > 2 mmol/L nonostante i liquidi. Segni d'allarme: confusione nuova, tachipnea, ipotensione, oliguria, cute marezzata. Interventi della prima ora: lattati, emocolture, antibiotico, liquidi, vasopressori se serve."},["news2","lattati","emocolture","shockdistributivo","pam"]],
["news2","NEWS2","Scala",["!NEWS2"],{d:"National Early Warning Score 2: punteggio di allerta precoce basato su FR, SpO₂, ossigeno, PA sistolica, FC, coscienza (incluso confusione nuova) e temperatura.",val:"Ogni parametro 0-3 punti. Totale 0-4 basso rischio; 5-6 o un parametro a 3: risposta urgente; ≥ 7: risposta d'emergenza.",ap:"Esempi di soglie: FR ≤ 8 = 3, 9-11 = 1, 12-20 = 0, 21-24 = 2, ≥ 25 = 3. FC ≤ 40 = 3, 41-50 = 1, 51-90 = 0, 91-110 = 1, 111-130 = 2, ≥ 131 = 3. PAS ≤ 90 = 3, 91-100 = 2, 101-110 = 1. T ≤ 35 = 3, 35,1-36 = 1, 38,1-39 = 1, ≥ 39,1 = 2. Confusione nuova o risposta solo a voce, dolore o nessuna = 3."},["sepsi","tachipnea"]],
["lattati","Lattati","Esame",["lattat[oi]"],{d:"Prodotto del metabolismo del glucosio quando le cellule ricevono poco ossigeno o la sua eliminazione è ridotta.",val:"Normali < 2 mmol/L.",ap:"Nella sepsi valori alti indicano ipoperfusione e prognosi peggiore; ≥ 4 mmol/L richiedono un trattamento aggressivo. Si ripetono per vedere la risposta alla terapia."},["sepsi","shock"]],
["emocolture","Emocolture","Esame",["emocoltur[ae]"],{d:"Campioni di sangue messi in flaconi di coltura per cercare batteri o funghi nel sangue.",ap:"Di solito almeno due set (flacone aerobio e anaerobio) da siti diversi, con antisepsi accurata della cute e dei tappi, prima dell'antibiotico se non lo ritarda. Il risultato richiede 24-72 ore."},["sepsi","antibiogramma"]],
["antibiogramma","Antibiogramma","Esame",["antibiogramma"],{d:"Test che indica a quali antibiotici il batterio isolato è sensibile o resistente.",ap:"Permette di passare dall'antibiotico empirico ad ampio spettro a quello mirato."},["emocolture","antibiotico"]],
["urinocoltura","Urinocoltura","Esame",["urinocoltura"],{d:"Coltura delle urine per identificare batteri.",ap:"Nel paziente con catetere si preleva dal punto dedicato del raccordo, dopo disinfezione, con siringa sterile; mai dalla sacca di raccolta. Un catetere a lungo termine è spesso colonizzato: la batteriuria senza sintomi non si tratta."},["catetere"]],
["catetere","Catetere vescicale","Dispositivo",["catetere vescicale","catetere"],{d:"Tubo inserito attraverso l'uretra nella vescica per drenare le urine.",ap:"È la principale causa di infezioni urinarie correlate all'assistenza: va posizionato solo se indicato, mantenuto con sistema chiuso e sacca sotto il livello della vescica, rivalutato ogni giorno e rimosso appena possibile."},["urinocoltura","sepsi"]],
["febbre","Febbre","Parametro",["febbre","febbril[ei]"],{d:"Aumento della temperatura corporea regolato dall'ipotalamo, di solito oltre 38°C.",ap:"Negli anziani e negli immunodepressi la sepsi può presentarsi senza febbre o con ipotermia."},["sepsi","paracetamolo"]],
["diuresioraria","Diuresi oraria","Parametro",["diuresi oraria","diuresi","oliguria"],{d:"Quantità di urina prodotta in un'ora.",val:"Obiettivo minimo nell'adulto ≥ 0,5 mL/kg/h. Sotto si parla di oliguria.",ap:"È un indicatore semplice della perfusione renale. Prima di segnalare un calo improvviso si controlla che il catetere non sia piegato o ostruito."},["bilancioidrico","sepsi","dannorenale"]],
["bilancioidrico","Bilancio idrico","Procedura",["bilancio idrico"],{d:"Confronto tra liquidi entrati (bevande, infusioni, nutrizione) e usciti (urine, drenaggi, vomito, feci liquide) in un periodo di tempo.",ap:"Si integra con il peso giornaliero, che stima meglio le variazioni di liquidi: 1 kg corrisponde circa a 1 litro."},["diuresioraria","furosemide"]],
["dannorenale","Danno renale acuto","Clinica",["danno renale acuto"],{d:"Riduzione rapida della funzione renale in ore o giorni: aumento della creatinina e/o riduzione della diuresi.",ap:"Cause pre-renali (ipoperfusione: disidratazione, sepsi, scompenso), renali (farmaci nefrotossici, emolisi), post-renali (ostruzione)."},["diuresioraria","sepsi"]],
["rc","Tempo di riempimento capillare","Segno",["tempo di riempimento capillare"],{d:"Tempo che serve alla cute per ritornare rosa dopo una pressione di 5 secondi sul polpastrello o sullo sterno.",val:"Normale ≤ 2-3 secondi.",ap:"Un tempo lungo indica ridotta perfusione periferica (shock, freddo)."},["shock"]],

/* ---------- RENE ED ELETTROLITI ---------- */
["potassio","Potassio (K⁺)","Parametro",["potassi[oa]","potassiemia","k⁺"],{d:"Il principale ione all'interno delle cellule. Determina il potenziale di riposo delle cellule di nervi e muscoli, compreso il cuore.",val:"Nel sangue 3,5-5,0 mmol/L (dentro le cellule circa 140).",ap:"Si sposta dentro le cellule con insulina, β2-agonisti e alcalosi; esce con acidosi, carenza di insulina, danno cellulare. Viene eliminato soprattutto dal rene."},["iperkaliemia","ipokaliemia","potenzialeriposo","pompana"]],
["iperkaliemia","Iperkaliemia","Clinica",["iperkaliemi[ac]"],{d:"Potassio nel sangue sopra 5,5 mmol/L; grave sopra 6,5 o con alterazioni ECG.",ap:"Cause: insufficienza renale, dialisi saltata, farmaci (ACE-inibitori, sartani, spironolattone, FANS), sostituti del sale, acidosi, danno cellulare. Sintomi: debolezza, parestesie, aritmie. Terapia: calcio per proteggere il cuore, insulina-glucosio e salbutamolo per spostarlo, dialisi o resine per eliminarlo."},["potassio","calciogluconato","ondet","dialisi"]],
["ipokaliemia","Ipokaliemia","Clinica",["ipokaliemi[ac]"],{d:"Potassio nel sangue sotto 3,5 mmol/L; grave sotto 2,5.",ap:"Cause: diuretici, vomito, diarrea, insulina, β2-agonisti, carenza di magnesio. Effetti: debolezza, crampi, stipsi, aritmie, aumentata tossicità della digossina. All'ECG onde T piatte e onde U. Il potassio EV si somministra diluito e lentamente, mai in bolo."},["potassio","furosemide","ondeu"]],
["iponatriemia","Iponatriemia","Clinica",["iponatriemi[ac]","sodiemia"],{d:"Sodio nel sangue sotto 135 mmol/L (valori normali 135-145).",ap:"Sintomi da nausea e cefalea fino a confusione, convulsioni e coma, soprattutto se si sviluppa rapidamente. Cause: diuretici, eccesso di acqua, SIADH, scompenso, cirrosi. Va corretta lentamente."},["furosemide"]],
["ipercalcemia","Ipercalcemia","Clinica",["ipercalcemi[ac]"],{d:"Calcio nel sangue troppo alto.",ap:"Cause: iperparatiroidismo, tumori. Sintomi: stipsi, poliuria, confusione, calcoli renali. All'ECG accorcia il QT."},["qt"]],
["pompana","Pompa Na⁺/K⁺-ATPasi","Fisiologia",["na⁺\\/k⁺-atpasi"],{d:"Proteina di membrana che, consumando ATP, porta 3 ioni sodio fuori dalla cellula e 2 ioni potassio dentro.",ap:"Mantiene il potassio alto dentro e il sodio alto fuori, base del potenziale di riposo. È stimolata da insulina e catecolamine."},["potassio","potenzialeriposo"]],
["potenzialeriposo","Potenziale di riposo","Fisiologia",["potenziale di riposo"],{d:"Differenza di carica elettrica tra interno ed esterno di una cellula a riposo: nelle cellule muscolari cardiache circa −90 mV.",ap:"Dipende soprattutto dal gradiente del potassio. Con potassio esterno alto il potenziale diventa meno negativo: molti canali del sodio si inattivano e la cellula conduce peggio. Il calcio alza la soglia e ripristina la distanza tra riposo e soglia."},["potassio","calciogluconato"]],
["insuffrenale","Insufficienza renale cronica","Clinica",["insufficienza renale","!IRC","renal[ei]"],{d:"Riduzione progressiva e irreversibile della funzione dei reni per più di 3 mesi.",ap:"Si classifica con l'eGFR. Conseguenze: ritenzione di liquidi, potassio e fosforo, acidosi, anemia, ipertensione, accumulo di farmaci (insulina, morfina, metformina, enoxaparina) da adattare."},["egfr","dialisi","iperkaliemia"]],
["egfr","eGFR","Esame",["!eGFR"],{d:"Velocità di filtrazione glomerulare stimata, calcolata dalla creatinina, dall'età e dal sesso.",val:"Normale ≥ 90 mL/min/1,73 m². 60-89 lieve riduzione; 30-59 moderata; 15-29 grave; < 15 insufficienza terminale.",ap:"Guida l'adattamento delle dosi dei farmaci eliminati dal rene."},["insuffrenale"]],
["dialisi","Emodialisi","Procedura",["emodialisi","dialisi"],{d:"Depurazione del sangue con una macchina che lo fa passare attraverso un filtro: elimina acqua in eccesso, potassio, urea e altre sostanze.",ap:"Di solito 3 sedute a settimana di circa 4 ore. Si accede tramite fistola arterovenosa o catetere venoso centrale. Saltare una seduta, soprattutto quella dopo il fine settimana, espone a iperkaliemia e sovraccarico."},["fistola","iperkaliemia"]],
["fistola","Fistola arterovenosa","Anatomia · Accesso",["fistola"],{d:"Collegamento chirurgico tra un'arteria e una vena del braccio, che rende la vena grande e robusta per la dialisi.",ap:"Sul braccio della fistola non si misura la pressione, non si fanno prelievi né infusioni. Ogni giorno si controlla il fremito (thrill) alla palpazione."},["dialisi"]],
["nefrone","Nefrone","Anatomia",["nefrone"],{d:"Unità funzionale del rene: circa un milione per rene.",ap:"Comprende glomerulo (filtra il plasma), tubulo contorto prossimale, ansa di Henle, tubulo contorto distale e dotto collettore, che modificano il filtrato fino all'urina."},["glomerulo","ansahenle","tubuloprossimale","tubulodistale","dottocollettore"]],
["glomerulo","Glomerulo","Anatomia",["glomerulo","glomerular[ei]"],{d:"Gomitolo di capillari dentro la capsula di Bowman: filtra il plasma formando l'ultrafiltrato.",ap:"Circa 180 litri di filtrato al giorno, poi riassorbito quasi tutto."},["nefrone"]],
["ansahenle","Ansa di Henle","Anatomia",["ansa di henle"],{d:"Tratto del nefrone a forma di U che scende nella midollare del rene e risale.",ap:"La parte discendente è permeabile all'acqua; il tratto ascendente spesso riassorbe sodio, potassio e cloro con il cotrasportatore Na⁺-K⁺-2Cl⁻ ma è impermeabile all'acqua. Così crea il gradiente che permette di concentrare l'urina. È la sede della furosemide."},["furosemide","nefrone"]],
["tubuloprossimale","Tubulo contorto prossimale","Anatomia",["tubulo contorto prossimale","tubulo prossimale"],{d:"Primo tratto del tubulo renale dopo il glomerulo.",ap:"Riassorbe circa due terzi di acqua e sodio filtrati, quasi tutto il glucosio, gli aminoacidi e gran parte del bicarbonato."},["nefrone","acetazolamide"]],
["tubulodistale","Tubulo contorto distale","Anatomia",["tubulo contorto distale","tubulo distale"],{d:"Tratto del tubulo dopo l'ansa di Henle.",ap:"Riassorbe sodio e cloro (sede dei tiazidici) e regola il calcio sotto l'azione del paratormone."},["tiazidici","nefrone"]],
["dottocollettore","Dotto collettore","Anatomia",["dotto collettore"],{d:"Tratto finale del nefrone, che raccoglie l'urina di più nefroni.",ap:"Sotto l'azione dell'aldosterone riassorbe sodio ed elimina potassio; sotto l'azione dell'ADH riassorbe acqua."},["aldosterone","adh","spironolattone"]],
["aldosterone","Aldosterone","Ormone",["aldosterone"],{d:"Ormone della corticale del surrene che fa riassorbire sodio e acqua ed eliminare potassio nel rene.",ap:"È stimolato dall'angiotensina II e dal potassio alto. ACE-inibitori e spironolattone ne riducono l'effetto: per questo possono alzare il potassio."},["dottocollettore","ramipril","spironolattone"]],
["adh","ADH (ormone antidiuretico)","Ormone",["!ADH"],{d:"Ormone prodotto dall'ipotalamo e liberato dalla neuroipofisi, detto anche vasopressina.",ap:"Fa riassorbire acqua nel dotto collettore e concentra l'urina. Aumenta con disidratazione e calo della pressione."},["dottocollettore"]],

/* ---------- ECG ---------- */
["ecg","ECG (elettrocardiogramma)","Esame",["!ECG","elettrocardiogramma","12 derivazioni"],{d:"Registrazione dell'attività elettrica del cuore. A 12 derivazioni guarda il cuore da 12 punti di vista; il monitor ne mostra di solito una o due.",ap:"Onda P: attivazione degli atri. Complesso QRS: attivazione dei ventricoli. Onda T: ripolarizzazione ventricolare. Intervalli PR e QT."},["ondet","qrs","fibrillazioneatriale"]],
["ondet","Onde T appuntite","Segno",["onde t","onda t"],{d:"Onde T alte, strette e simmetriche, a tenda.",ap:"Sono spesso il primo segno ECG di iperkaliemia. Possono comparire anche nella fase iniziale di un infarto (T iperacute)."},["iperkaliemia","ecg"]],
["qrs","Complesso QRS","Esame",["!QRS"],{d:"Parte dell'ECG che rappresenta l'attivazione elettrica dei ventricoli.",val:"Durata normale < 120 ms (3 quadretti piccoli).",ap:"Si allarga con blocchi di branca, iperkaliemia grave, alcuni farmaci tossici (antidepressivi triciclici)."},["ecg","iperkaliemia"]],
["pr","Onda P e intervallo PR","Esame",["!PR","onde p","onda p"],{d:"L'onda P rappresenta l'attivazione degli atri; l'intervallo PR va dall'inizio della P all'inizio del QRS.",val:"PR normale 120-200 ms.",ap:"PR lungo: rallentamento della conduzione atrioventricolare (farmaci, iperkaliemia, blocchi)."},["ecg"]],
["qt","Intervallo QT","Esame",["!QT"],{d:"Intervallo dall'inizio del QRS alla fine dell'onda T: la durata totale di attivazione e ripolarizzazione dei ventricoli.",ap:"Si corregge per la frequenza (QTc). Lungo: rischio di torsione di punta (farmaci, ipokaliemia, ipomagnesiemia). Corto: ipercalcemia."},["ecg","ipercalcemia"]],
["ondeu","Onde U","Esame",["onde u"],{d:"Piccola onda dopo l'onda T, visibile soprattutto in V2-V3.",ap:"Diventa evidente nell'ipokaliemia, insieme a onde T piatte."},["ipokaliemia"]],

/* ---------- POSIZIONI, VIE, PROCEDURE ---------- */
["trendelenburg","Trendelenburg","Posizione",["trendelenburg"],{d:"Posizione supina con il letto inclinato in modo che la testa sia più bassa del bacino.",ap:"Si usa per alcune procedure (es. inserimento di un catetere venoso centrale in giugulare o succlavia, alcune chirurgie). Aumenta il ritorno venoso ma spinge i visceri sul diaframma: peggiora respiro e congestione polmonare."},["precarico","diaframma"]],
["fowler","Posizione di Fowler","Posizione",["fowler","semiseduta","semiseduto"],{d:"Paziente con lo schienale sollevato: semi-Fowler circa 30°, Fowler circa 45-60°, Fowler alta circa 90°.",ap:"Migliora la respirazione e riduce il rischio di aspirazione. Con le gambe declivi riduce anche il ritorno venoso."},["ortopnea"]],
["pls","Posizione laterale di sicurezza","Posizione",["posizione laterale di sicurezza"],{d:"Paziente sul fianco con il capo esteso e la bocca verso il basso.",ap:"Per una persona incosciente che respira normalmente: mantiene aperte le vie aeree e fa defluire vomito e secrezioni."},[]],
["intramuscolo","Via intramuscolare (IM)","Via di somministrazione",["intramuscol[oa]","!IM"],{d:"Iniezione di un farmaco nella massa di un muscolo.",ap:"Sedi: vasto laterale della coscia, deltoide, ventrogluteo. L'assorbimento è più rapido del sottocute e dipende dal flusso di sangue al muscolo."},["vastolaterale"]],
["vastolaterale","Vasto laterale (coscia anterolaterale)","Anatomia",["coscia anterolaterale","vasto laterale"],{d:"Muscolo della parte esterna della coscia, uno dei quattro capi del quadricipite.",ap:"È la sede raccomandata per l'adrenalina IM: ben vascolarizzato, lontano da grandi vasi e nervi, assorbimento rapido. Si inietta nel terzo medio della faccia anterolaterale."},["adrenalina","intramuscolo"]],
["ev","Via endovenosa (EV)","Via di somministrazione",["!EV","endovenos[oa]"],{d:"Somministrazione direttamente in vena, attraverso un ago cannula o un catetere venoso.",ap:"Effetto immediato e dosaggio preciso; più rischi (flebite, stravaso, infezione, reazioni rapide)."},["flebite"]],
["flebite","Flebite","Clinica",["flebite","vena si infiamma"],{d:"Infiammazione della parete di una vena, spesso nella sede di un ago cannula.",ap:"Segni: dolore, arrossamento, calore, cordone palpabile lungo la vena. Cause: farmaci irritanti o ipertonici, cannula troppo grande o lasciata a lungo, infezione. Si rimuove la cannula e si valuta con una scala dedicata."},["ev"]],
["stravaso","Stravaso","Clinica",["stravas[ai]"],{d:"Uscita di una soluzione dalla vena nei tessuti circostanti.",ap:"Con farmaci irritanti o vescicanti (calcio, potassio, glucosio ipertonico, bicarbonato, alcuni chemioterapici) può causare necrosi. Si ferma l'infusione e si segue il protocollo."},["flebite","calciogluconato"]],
["sottocute","Via sottocutanea","Via di somministrazione",["sottocute"],{d:"Iniezione nel tessuto adiposo sotto la cute (addome, braccio, coscia).",ap:"Assorbimento più lento e regolare della via IM. Usata per insulina ed eparine. In un paziente disidratato o in shock l'assorbimento diventa imprevedibile."},["glargine","enoxaparina"]],
["accessovenoso","Accesso venoso / ago cannula","Dispositivo",["accesso venoso","ago cannula","cannula","deflussore"],{d:"Catetere corto inserito in una vena periferica per infusioni e farmaci EV. Il deflussore è il tubo che collega la sacca all'accesso.",ap:"Si controlla almeno a ogni turno (flebite, infiltrazione, medicazione). Il calibro si sceglie in base all'uso: più grande per trasfusioni e boli rapidi."},["ev","flebite"]],
["aerosol","Aerosol / nebulizzazione","Procedura",["aerosol","nebulizza[a-z]+"],{d:"Trasformazione di un farmaco liquido in goccioline fini da inalare con maschera o boccaglio.",ap:"Si usa per broncodilatatori e altri farmaci quando il paziente non riesce a usare uno spray. Nella BPCO ipercapnica si preferisce nebulizzare con aria compressa invece che con ossigeno ad alto flusso."},["salbutamolo"]],
["distanziatore","Distanziatore","Dispositivo",["distanziatore"],{d:"Camera che si collega allo spray predosato e trattiene il farmaco perché il paziente lo inali con calma.",ap:"Migliora la quantità di farmaco che arriva ai bronchi e riduce quello che si deposita in bocca."},["salbutamolo"]]
];
